// Bank soal Simulasi UTS Manajemen Keuangan Lanjutan (MKL).
// t = materi (1 Corporate Governance, 2 Capital Budgeting, 3 Cost of Capital), d = "e" (Easy) / "h" (Hard)
// q = soal, tb = tabel data opsional (baris pertama = header), o = [teks opsi, catatan kenapa benar/salah],
// a = indeks opsi benar, x = pembahasan (baris baru = langkah). Urutan opsi diacak saat latihan.
window.QUESTIONS = [

/* ================= MATERI 1 · CORPORATE GOVERNANCE · EASY (10) ================= */
{t:1,d:"e",
q:"Menurut materi, Corporate Governance didefinisikan sebagai…",
o:[["Sistem prinsip, kebijakan, prosedur, dan akuntabilitas yang dipakai stakeholders untuk mengatasi konflik kepentingan","Tepat. Ini definisi di slide: intinya sistem untuk mengatasi konflik kepentingan."],
["Proses analisis proyek jangka panjang untuk menentukan proyek mana yang dieksekusi dan dimasukkan ke anggaran modal","Ini definisi Capital Budgeting, bukan Corporate Governance."],
["Kumpulan laporan keuangan tahunan yang wajib diaudit dan dipublikasikan oleh perusahaan terbuka kepada regulator","Laporan keuangan hanyalah salah satu alat transparansi, bukan definisi tata kelola."],
["Struktur organisasi yang menempatkan direksi di atas manajer agar setiap keputusan manajer selalu disetujui pemilik","Tata kelola tidak didefinisikan sebagai hierarki persetujuan. Fokusnya adalah mengatasi konflik kepentingan."]],
a:0,x:"Kata kunci definisi Corporate Governance (CG): sistem prinsip, kebijakan, prosedur, tanggung jawab dan akuntabilitas yang dipakai stakeholders untuk MENGATASI KONFLIK KEPENTINGAN dalam bentuk usaha \"corporate\".\nKonflik kepentingan muncul karena pemilik (shareholders) menyerahkan pengelolaan perusahaan kepada manajer, dan kepentingan keduanya bisa berbeda."},

{t:1,d:"e",
q:"Berikut ini yang BUKAN merupakan tujuan (objective) dari sistem Corporate Governance adalah…",
o:[["Menghilangkan atau mengurangi konflik kepentingan","Ini tujuan pertama CG menurut materi."],
["Memastikan aset perusahaan digunakan secara efisien dan produktif","Ini tujuan kedua CG, demi kepentingan terbaik investor dan stakeholder lain."],
["Memaksimalkan kompensasi dan fasilitas bagi manajemen","Benar, ini bukan tujuan CG. Justru penggunaan fasilitas berlebihan oleh manajer adalah contoh konflik yang ingin dicegah."],
["Menjaga agar aset dipakai demi kepentingan terbaik investor","Ini bagian dari tujuan kedua CG."]],
a:2,x:"Dua tujuan CG di materi:\n1. Menghilangkan atau mengurangi konflik kepentingan.\n2. Memastikan aset perusahaan digunakan secara efisien dan produktif, dalam kepentingan terbaik investor dan stakeholder lainnya.\nMemaksimalkan kompensasi manajer justru bertentangan dengan kepentingan pemilik (contoh agency problem)."},

{t:1,d:"e",
q:"Prinsip Corporate Governance yang menuntut perusahaan menyediakan informasi secara tepat waktu, memadai, jelas, akurat, dapat diperbandingkan, dan mudah diakses oleh pemangku kepentingan adalah…",
o:[["Akuntabilitas (Accountability)","Akuntabilitas berkaitan dengan pertanggungjawaban kinerja, rincian tugas, pengendalian internal, reward & punishment."],
["Transparansi (Transparency)","Tepat. Transparansi = keterbukaan informasi yang tepat waktu, memadai, jelas, akurat, dan mudah diakses."],
["Fairness (Kewajaran)","Fairness berkaitan dengan perlakuan setara dan wajar terhadap pemangku kepentingan."],
["Independensi (Independency)","Independensi berkaitan dengan bebas dari dominasi dan intervensi pihak lain."]],
a:1,x:"Lima prinsip CG (TARIF): Transparansi, Akuntabilitas, Responsibilitas, Independensi, Fairness.\nTransparansi: informasi tepat waktu, memadai, jelas, akurat, dapat diperbandingkan, mudah diakses, tetap menjaga kerahasiaan sesuai UU, dan kebijakan perusahaan tertulis serta dikomunikasikan.\nKata kunci soal ini: \"menyediakan informasi\", jadi jawabannya Transparansi."},

{t:1,d:"e",
q:"Sebuah perusahaan menetapkan rincian tugas yang jelas untuk setiap jabatan, sistem pengendalian internal yang efektif, ukuran kinerja, serta sistem reward and punishment. Prinsip CG yang diterapkan adalah…",
o:[["Responsibilitas (Responsibility)","Responsibilitas berkaitan dengan kepatuhan pada peraturan dan tanggung jawab sosial serta lingkungan."],
["Transparansi (Transparency)","Transparansi berkaitan dengan keterbukaan informasi, bukan sistem kinerja internal."],
["Akuntabilitas (Accountability)","Tepat. Rincian tugas, pengendalian internal, ukuran kinerja, serta reward & punishment adalah ciri akuntabilitas."],
["Independensi (Independency)","Independensi berkaitan dengan bebas dari dominasi dan benturan kepentingan."]],
a:2,x:"Akuntabilitas = perusahaan dapat mempertanggungjawabkan kinerjanya secara transparan dan wajar. Cirinya:\n• ada rincian tugas dan tanggung jawab;\n• ada sistem pengendalian internal yang efektif;\n• ada ukuran kinerja serta reward and punishment system;\n• berpegang pada etika bisnis dan code of conduct."},

{t:1,d:"e",
q:"Prinsip yang menyatakan bahwa perusahaan harus dikelola sehingga masing-masing organ perusahaan tidak saling mendominasi dan tidak dapat diintervensi pihak lain disebut…",
o:[["Independensi","Tepat. Independensi = bebas dominasi, bebas intervensi, bebas benturan kepentingan, keputusan diambil objektif."],
["Fairness","Fairness berkaitan dengan kesetaraan perlakuan antar pemangku kepentingan."],
["Akuntabilitas","Akuntabilitas berkaitan dengan pertanggungjawaban kinerja."],
["Responsibilitas","Responsibilitas berkaitan dengan kepatuhan hukum dan tanggung jawab sosial."]],
a:0,x:"Independensi: perusahaan dikelola secara independen sehingga organ perusahaan tidak saling mendominasi dan tidak dapat diintervensi pihak lain. Tujuannya agar keputusan diambil secara OBJEKTIF, bebas dari conflict of interest dan tekanan."},

{t:1,d:"e",
q:"Dalam agency theory, pemegang saham (shareholders) berperan sebagai … sedangkan manajer berperan sebagai …",
o:[["Agent (decision-making specialist); principal (risk-bearing specialist)","Terbalik. Shareholders adalah principal, manajer adalah agent."],
["Principal (risk-bearing specialist); agent (decision-making specialist)","Tepat. Shareholders menanggung risiko (principal), manajer ahli pengambil keputusan (agent)."],
["Principal (decision-making specialist); agent (risk-bearing specialist)","Peran spesialisnya tertukar. Yang menanggung risiko adalah pemilik."],
["Stakeholder (monitoring specialist); agent (risk-bearing specialist)","Istilah ini tidak ada di materi agency theory."]],
a:1,x:"Agency relationship: shareholders (principals) = risk-bearing specialist, mempekerjakan (hire) manajer. Manajer (agents) = managerial decision-making specialist.\nMasalah muncul saat tujuan principal dan agent berbeda, dan sulit atau mahal bagi principal untuk memverifikasi perilaku agent."},

{t:1,d:"e",
q:"Menurut materi, konflik antara Direksi (Board of Directors) dan Shareholder terutama terjadi ketika…",
o:[["Manajer menggunakan fasilitas kantor secara berlebihan","Ini contoh konflik Manager–Shareholder, bukan Director–Shareholder."],
["Pemegang saham menjual sahamnya di pasar sekunder","Penjualan saham bukan sumber konflik yang dibahas."],
["Dewan direksi tidak bersifat independen dari manajer","Tepat. Misalnya anggota dewan punya hubungan pribadi dengan manajer sehingga keputusannya bias dan kompromistis."],
["Perusahaan membagikan dividen lebih kecil dari tahun lalu","Kebijakan dividen bukan contoh sumber konflik di materi ini."]],
a:2,x:"Dua sumber konflik utama:\n1. Manager–Shareholder: contohnya Enron dan Parmalat, perluasan bisnis yang tidak dikehendaki pemilik, dan penggunaan fasilitas kantor berlebihan.\n2. Director–Shareholder: direksi seharusnya menjadi penghubung yang memonitor manajer dan menyetujui strategi. Konflik terjadi ketika direksi TIDAK INDEPENDEN, misalnya punya personal relationship dengan manajer, sehingga keputusannya bias dan cenderung kompromi."},

{t:1,d:"e",
q:"Berikut ini yang BUKAN termasuk potensi dampak faktor ESG (Environmental, Social, Governance) terhadap perusahaan menurut materi adalah…",
o:[["Legislative and regulatory risk","Termasuk dampak ESG di materi."],
["Reputational risk","Termasuk dampak ESG di materi."],
["Operating risk","Termasuk dampak ESG di materi."],
["Exchange rate risk","Benar, ini bukan dampak ESG. Risiko nilai tukar adalah risiko pasar keuangan, tidak masuk daftar di materi."]],
a:3,x:"Empat potensi dampak faktor ESG terhadap perusahaan:\na. Legislative and regulatory risk\nb. Legal risk\nc. Reputational risk\nd. Operating risk\nExchange rate risk (risiko kurs) tidak ada dalam daftar."},

{t:1,d:"e",
q:"Corporate governance yang lemah dapat menimbulkan beberapa risiko. Risiko berupa penyalahgunaan (misappropriation) aset perusahaan oleh manajer disebut…",
o:[["Accounting risk","Accounting risk adalah laporan yang tidak lengkap, menyesatkan, atau salah saji material."],
["Liability risk","Liability risk adalah kewajiban berlebihan, bisa berupa off-balance sheet obligation."],
["Asset risk","Tepat. Asset risk = aset disalahgunakan oleh manajer."],
["Strategic policy risk","Strategic policy risk berkaitan dengan kebijakan strategis yang merugikan, bukan penyalahgunaan aset."]],
a:2,x:"Risiko dari weak corporate governance:\na. Accounting risk: laporan tidak lengkap, menyesatkan, atau salah saji material.\nb. Asset risk: aset disalahgunakan (misappropriate) oleh manajer.\nc. Liability risk: kewajiban berlebihan, bisa berupa off-balance sheet obligation.\nd. Strategic policy risk."},

{t:1,d:"e",
q:"Menurut materi pengantar, apa yang menjadi fokus manajer dalam meningkatkan nilai perusahaan?",
o:[["Memperbesar laba akuntansi tahun berjalan, walaupun arus kas masuknya baru diterima beberapa tahun kemudian","Nilai ditentukan arus kas, bukan laba akuntansi. Arus kas yang lebih lambat justru menurunkan nilai."],
["Memperbesar expected cash flows, mempercepat penerimaannya, dan mengurangi risikonya","Tepat. Tiga faktor: besaran arus kas, waktu (semakin cepat semakin baik), dan risiko (investor menghindari risiko)."],
["Memperbesar aset tetap perusahaan sebanyak mungkin agar total aset di neraca selalu terlihat meningkat","Menambah aset tidak otomatis menambah nilai jika tidak menghasilkan arus kas."],
["Menaikkan harga pasar saham dalam jangka pendek walaupun nilai intrinsik perusahaan tidak berubah sama sekali","Materi membedakan market value dan nilai intrinsik. Tujuannya nilai fundamental, bukan sekadar harga jangka pendek."]],
a:1,x:"Tiga faktor yang dipertimbangkan:\n1. Aset keuangan, termasuk saham, berharga bila menghasilkan aliran kas.\n2. Waktu arus kas penting: semakin cepat diterima semakin baik.\n3. Investor cenderung menghindari risiko.\nJadi fokus manajer: meningkatkan ukuran expected cash flows, mempercepat pengembalian, dan mengurangi risiko.\nValue = FCF1/(1+WACC)^1 + FCF2/(1+WACC)^2 + … (catatan: di slide tertulis (1 − WACC) pada baris pertama, itu salah ketik. Yang benar (1 + WACC))."},

/* ================= MATERI 1 · CORPORATE GOVERNANCE · HARD (10) ================= */
{t:1,d:"h",
q:"PT Sinar Abadi membuka lowongan dengan syarat yang sama bagi semua pelamar tanpa membedakan suku, agama, gender, dan kondisi fisik. Perusahaan juga membuka forum bagi pemegang saham minoritas dan karyawan untuk memberi masukan bagi kepentingan perusahaan. Prinsip CG yang paling tepat menggambarkan kebijakan ini adalah…",
o:[["Responsibilitas, karena perusahaan menunjukkan kepedulian sosial kepada masyarakat sekitar","Responsibilitas menekankan kepatuhan hukum dan tanggung jawab sosial serta lingkungan, bukan kesetaraan perlakuan."],
["Transparansi, karena perusahaan membuka informasi lowongan kepada publik secara luas","Fokus kasus ini perlakuan yang setara dan kesempatan memberi masukan, bukan keterbukaan informasi."],
["Fairness, karena perusahaan memberi perlakuan setara dan kesempatan menyampaikan pendapat","Tepat. Kesempatan yang sama dalam rekrutmen dan karier, serta kesempatan memberi masukan, adalah ciri Fairness."],
["Independensi, karena keputusan rekrutmen bebas dari pengaruh pihak luar perusahaan","Independensi soal bebas dominasi dan intervensi dalam pengambilan keputusan, bukan kesetaraan pelamar."]],
a:2,x:"Fairness (kewajaran dan kesetaraan), menurut slide:\n• memperhatikan kepentingan pemegang saham dan stakeholders berdasarkan asas kewajaran dan kesetaraan;\n• memberi kesempatan untuk memberi masukan dan menyampaikan pendapat;\n• perlakuan setara sesuai manfaat dan kontribusi;\n• kesempatan sama dalam penerimaan karyawan dan berkarier tanpa membedakan suku, agama, ras, golongan, gender, dan kondisi fisik.\nKasus ini memuat dua ciri sekaligus (rekrutmen setara dan forum masukan), jadi jawabannya Fairness."},

{t:1,d:"h",
q:"Sebuah perusahaan tambang membangun instalasi pengolahan limbah sesuai regulasi, menerapkan prinsip kehati-hatian dalam operasional, dan menjalankan program pemberdayaan masyarakat sekitar tambang. Prinsip CG yang paling tepat adalah…",
o:[["Akuntabilitas, karena perusahaan mempertanggungjawabkan seluruh kinerjanya kepada pemegang saham","Akuntabilitas fokus pada pertanggungjawaban kinerja internal (rincian tugas, kontrol internal, reward & punishment)."],
["Responsibilitas, karena perusahaan patuh regulasi serta peduli masyarakat dan lingkungan","Tepat. Patuh perundang-undangan, prinsip kehati-hatian, dan tanggung jawab sosial serta lingkungan adalah ciri Responsibilitas."],
["Fairness, karena perusahaan memperlakukan masyarakat sekitar setara dengan pemegang saham","Fairness soal kesetaraan perlakuan antar stakeholders, bukan kepatuhan regulasi dan tanggung jawab lingkungan."],
["Transparansi, karena program pemberdayaan masyarakat diumumkan dalam laporan tahunan","Soal ini tidak menyebut pengungkapan informasi. Fokusnya kepatuhan dan tanggung jawab sosial."]],
a:1,x:"Responsibilitas:\n• patuh pada peraturan perundang-undangan;\n• melaksanakan tanggung jawab terhadap masyarakat dan lingkungan;\n• berpegang pada prinsip kehati-hatian;\n• peduli masyarakat dan kelestarian lingkungan (tanggung jawab sosial).\nPengecoh tersulit adalah Akuntabilitas. Bedakan: Akuntabilitas = pertanggungjawaban KINERJA (internal), Responsibilitas = kepatuhan hukum dan tanggung jawab SOSIAL/LINGKUNGAN (eksternal)."},

{t:1,d:"h",
q:"CEO sebuah perusahaan makanan terus mengakuisisi bisnis yang tidak berkaitan (properti, tambang, dan media), padahal pemegang saham tidak menghendakinya. Motif CEO adalah agar risiko kehilangan pekerjaannya turun dan kompensasinya naik karena perusahaan makin besar. Masalah ini dan solusi yang sesuai materi adalah…",
o:[["Director–shareholder conflict; solusinya mengganti seluruh dewan direksi dengan pihak keluarga pemilik","Pelakunya manajer (CEO), bukan direksi. Mengganti direksi dengan keluarga pemilik juga bukan solusi di materi."],
["Overdiversification (agency problem); solusinya incentive-based performance contract dan monitoring oleh board","Tepat. Overdiversification adalah contoh agency problem di materi. Solusinya kontrak berbasis insentif, monitoring oleh board, dan managerial labor market."],
["Overdiversification (agency problem); solusinya menaikkan gaji tetap CEO agar tidak lagi melakukan ekspansi","Gaji tetap yang lebih tinggi tidak menyelaraskan kepentingan. Materi menyarankan kontrak berbasis kinerja (insentif)."],
["Strategic policy risk; solusinya menerbitkan obligasi agar dana untuk ekspansi bisnis menjadi terbatas","Strategic policy risk adalah risiko dari CG yang lemah, bukan nama masalahnya. Solusi penerbitan obligasi tidak dibahas."]],
a:1,x:"Agency problem terjadi bila tujuan principal dan agent bertentangan, dan sulit atau mahal bagi principal memverifikasi perilaku agent.\nContoh di materi: OVERDIVERSIFICATION, karena diversifikasi produk menurunkan employment risk manajer dan menaikkan kompensasinya.\nSolusi: (1) incentive-based performance contracts, (2) mekanisme monitoring seperti board of directors, (3) mekanisme penegakan seperti managerial labor market."},

{t:1,d:"h",
q:"Salah satu anggota dewan direksi PT Mega adalah adik ipar CEO. Dalam rapat, dewan cenderung menyetujui usulan CEO tanpa pemeriksaan kritis. Analisis yang paling tepat adalah…",
o:[["Manager–shareholder conflict, karena manajer memakai fasilitas kantor demi kepentingan pribadinya","Kasus ini tidak menyebut penyalahgunaan fasilitas. Masalahnya ada pada direksi yang tidak independen."],
["Director–shareholder conflict, karena direksi tidak independen sehingga keputusannya bias dan kompromistis","Tepat. Hubungan personal direksi dengan manajer membuat fungsi monitoring tidak berjalan."],
["Tidak ada konflik selama keputusan yang diambil CEO terbukti meningkatkan laba perusahaan tahun berjalan","Konflik ada pada struktur dan independensi pengawasan, bukan pada hasil laba sesaat."],
["Konflik antara controlling dan minority shareholder, karena CEO juga merupakan pemegang saham mayoritas","Soal tidak menyebut CEO sebagai pemegang saham mayoritas. Masalahnya ada pada independensi direksi."]],
a:1,x:"Direksi berfungsi memonitor manajer dan menyetujui kebijakan serta strategi. Konflik Director–Shareholder terjadi ketika dewan TIDAK INDEPENDEN.\nContoh di slide persis seperti kasus ini: anggota dewan punya personal relationship dengan manajer, sehingga keputusan bias dan cenderung kompromi.\nKaitannya dengan evaluasi CG: \"board composition and independence\" adalah poin pertama yang dinilai."},

{t:1,d:"h",
q:"Keluarga Wijaya memiliki 75% saham PT Cahaya (perusahaan terbuka). Perusahaan lalu membeli bahan baku dari perusahaan milik keluarga Wijaya dengan harga 20% di atas harga pasar. Jenis konflik dan poin evaluasi CG yang paling relevan adalah…",
o:[["Konflik manajer vs shareholder; poin evaluasinya frequency of separate sessions of independent directors","Masalah utamanya pemilik pengendali merugikan pemegang saham minoritas, bukan manajer vs pemilik."],
["Konflik controlling vs minority shareholder; poin evaluasinya insider or related-party transactions","Tepat. Pada perusahaan closely held, konflik terjadi antara pemegang saham pengendali dan minoritas. Pembelian dari perusahaan keluarga adalah related-party transaction."],
["Konflik controlling vs minority shareholder; poin evaluasinya whether the board is elected annually","Jenis konfliknya benar, tetapi poin evaluasi yang paling relevan untuk transaksi dengan pihak berelasi adalah related-party transactions."],
["Konflik director vs shareholder; poin evaluasinya qualification of the directors serta komite nominasi","Tidak ada indikasi masalah kualifikasi direksi. Masalahnya transaksi dengan pihak berelasi."]],
a:1,x:"Karakteristik bisnis dan konflik:\n1. Dispersed ownership: perusahaan memberi imbalan lebih besar kepada manajemen (insider ownership).\n2. Closely held (kepemilikan terkonsentrasi): konflik antara CONTROLLING dan MINORITY shareholder.\n3. BUMN.\n4. Agent bertindak untuk kepentingan sendiri.\nMembeli dari perusahaan milik pemegang saham pengendali di atas harga pasar memindahkan kekayaan dari minoritas ke pengendali. Poin evaluasi CG yang relevan: (m) insider or related-party transactions."},

{t:1,d:"h",
q:"Seorang analis menilai kualitas corporate governance sebuah perusahaan. Dari daftar berikut, manakah yang TIDAK termasuk guideline evaluasi CG di materi?",
o:[["Board self-assessment practices dan frekuensi sesi terpisah direktur independen","Keduanya termasuk dalam guideline (poin e dan f)."],
["Komite audit dan pengawasan audit, serta komite nominasi dan komite kompensasi","Termasuk guideline (poin g, h, i)."],
["Pertumbuhan laba per saham (EPS) selama lima tahun terakhir dibanding pesaing","Benar, ini bukan guideline evaluasi CG. EPS adalah ukuran kinerja keuangan, bukan kualitas tata kelola."],
["Respons dewan terhadap proxy vote pemegang saham dan penggunaan penasihat independen","Termasuk guideline (poin j dan n)."]],
a:2,x:"Guideline evaluasi CG (14 poin): a. board composition & independence; b. chairman independen; c. kualifikasi direktur; d. board dipilih tahunan atau staggered; e. board self-assessment; f. frekuensi sesi terpisah direktur independen; g. audit committee & audit oversight; h. nominating committee; i. compensation committee & kompensasi manajemen; j. penggunaan independent legal/expert counsel; k. statement of governance policies; l. disclosure & transparency; m. insider/related-party transactions; n. respons board terhadap shareholder proxy votes.\nKinerja EPS tidak termasuk."},

{t:1,d:"h",
q:"Sebuah perusahaan memindahkan utang besar ke entitas khusus (SPV) agar tidak tercatat di neraca, sehingga rasio utangnya terlihat rendah. Risiko akibat corporate governance yang lemah yang PALING tepat menggambarkan kasus ini adalah…",
o:[["Accounting risk, karena laporan keuangan menjadi tidak lengkap dan menyesatkan","Laporan memang menyesatkan, tetapi materi secara spesifik mengaitkan off-balance sheet obligation dengan liability risk."],
["Asset risk, karena aset perusahaan disalahgunakan oleh manajer untuk kepentingan pribadi","Kasus ini tentang kewajiban (utang), bukan penyalahgunaan aset."],
["Liability risk, karena ada kewajiban berlebihan yang disembunyikan di luar neraca","Tepat. Di materi: Liability risk = excessive obligations, can lead to off-balance sheet obligation."],
["Strategic policy risk, karena manajer mengambil strategi ekspansi yang terlalu berisiko","Kasus ini tidak membahas strategi ekspansi."]],
a:2,x:"Weak CG menimbulkan:\na. Accounting risk: laporan tidak lengkap, menyesatkan, salah saji material.\nb. Asset risk: aset disalahgunakan manajer.\nc. Liability risk: kewajiban berlebihan, bisa menjadi OFF-BALANCE SHEET obligation.\nd. Strategic policy risk.\nKata kunci \"utang tidak tercatat di neraca\" = off-balance sheet = liability risk. Accounting risk adalah pengecoh terdekat, tetapi materi mengaitkan off-balance sheet langsung dengan liability risk."},

{t:1,d:"h",
q:"Warga di sekitar pabrik PT Kimia Jaya menggugat perusahaan ke pengadilan karena pencemaran sungai, dan perusahaan berpotensi membayar ganti rugi besar. Dari sudut pandang faktor ESG, risiko yang PALING langsung muncul dari gugatan tersebut adalah…",
o:[["Legislative and regulatory risk","Risiko ini muncul dari perubahan undang-undang atau regulasi (misalnya aturan emisi baru), bukan dari gugatan pihak lain."],
["Legal risk","Tepat. Gugatan hukum dan potensi ganti rugi adalah legal risk."],
["Operating risk","Operating risk menyangkut gangguan operasional. Gugatan di pengadilan paling langsung termasuk legal risk."],
["Liability risk","Liability risk adalah kategori risiko dari weak corporate governance (kewajiban tersembunyi), bukan daftar dampak ESG."]],
a:1,x:"Dampak faktor ESG: (a) legislative & regulatory risk: perubahan UU atau regulasi; (b) legal risk: tuntutan hukum atau gugatan; (c) reputational risk: citra rusak; (d) operating risk: gangguan operasi.\nKasus gugatan warga paling langsung = legal risk. Reputasi juga bisa terdampak, tetapi soal meminta risiko yang paling langsung dari gugatan.\nHati-hati: liability risk termasuk daftar risiko weak governance, bukan daftar dampak ESG."},

{t:1,d:"h",
q:"Menurut materi, agency problem terjadi ketika…",
o:[["Manajer memiliki sebagian saham perusahaan sehingga ia sekaligus menjadi pemilik dan pengelola","Insider ownership justru disebut sebagai cara menyelaraskan kepentingan, bukan definisi agency problem."],
["Tujuan principal dan agent bertentangan, dan sulit atau mahal bagi principal memverifikasi perilaku agent","Tepat. Dua syarat ini harus ada bersamaan."],
["Tujuan principal dan agent bertentangan, walaupun principal dapat mengawasi agent dengan mudah dan murah","Jika verifikasi mudah dan murah, principal bisa mencegah penyimpangan, sehingga masalahnya tidak berkembang."],
["Pemegang saham dan kreditor berbeda pendapat mengenai besaran dividen yang dibagikan perusahaan","Ini bukan definisi agency problem di materi (yang dibahas hubungan shareholders dan manajer)."]],
a:1,x:"Definisi di slide: \"Agency problem occur when the desires or goals of the principal and agent conflict AND it is difficult or expensive for the principal to verify that the agent has behaved appropriately.\"\nJadi ada dua syarat: (1) tujuan bertentangan, (2) verifikasi sulit atau mahal. Pengecoh C hanya memenuhi syarat pertama."},

{t:1,d:"h",
q:"Menurut materi pengantar, FCF = Sales Revenue − Operating costs − Operating taxes − Required investments in operating capital. Sebuah perusahaan memiliki Sales Revenue $5.000, Operating costs $3.200, Operating taxes $540, dan Required investment in operating capital $600. Berapa Free Cash Flow (FCF) perusahaan?",
o:[["$1.260","Ini belum dikurangi investasi modal operasi ($600)."],
["$660","Tepat. 5.000 − 3.200 − 540 − 600 = 660."],
["$1.200","Ini lupa mengurangi pajak operasi ($540)."],
["$1.800","Ini hanya laba operasi sebelum pajak dan investasi (5.000 − 3.200)."]],
a:1,x:"FCF = Sales Revenue − Operating costs − Operating taxes − Required investments in operating capital.\n= 5.000 − 3.200 − 540 − 600 = $660.\nFCF = arus kas yang tersedia untuk didistribusikan kepada SELURUH investor (kreditor dan pemegang saham). Nilai perusahaan = PV dari FCF yang didiskonto dengan WACC.",
xl:{"s":["Ketik label di kolom A dan angkanya di kolom B (baris 1–4).","Di B5 ketik =B1-B2-B3-B4 lalu Enter."],"g":[["Sales Revenue","5000"],["Operating costs","3200"],["Operating taxes","540"],["Investasi modal operasi","600"],["FCF",{"f":"=B1-B2-B3-B4","v":"660"}]]}},

/* ================= MATERI 2 · CAPITAL BUDGETING · EASY (15) ================= */
{t:2,d:"e",
q:"Net Present Value (NPV) didefinisikan sebagai…",
o:[["Discount rate yang membuat nilai sekarang arus kas masuk sama dengan biaya investasi","Ini definisi IRR."],
["Nilai sekarang arus kas masuk dikurangi nilai sekarang total biaya investasinya","Tepat. NPV = PV arus kas masuk − PV biaya (sudah memperhitungkan nilai waktu uang)."],
["Jumlah arus kas masuk tanpa diskonto dikurangi investasi awal","Tanpa diskonto berarti mengabaikan nilai waktu uang. Ini sama dengan NPV pada r = 0%."],
["Waktu yang dibutuhkan proyek untuk mengembalikan investasi awal","Ini definisi payback period."]],
a:1,x:"NPV = CF0 + CF1/(1+r)^1 + CF2/(1+r)^2 + … + CFn/(1+r)^n, dengan CF0 = investasi awal (negatif).\nNPV menggambarkan seberapa besar kontribusi proyek terhadap kekayaan pemegang saham. Semakin besar NPV, semakin besar nilai proyek.\nDi Excel: =NPV(rate; CF1:CFn) + CF0. Ingat: CF0 ditambahkan di luar fungsi NPV."},

{t:2,d:"e",
q:"Internal Rate of Return (IRR) adalah discount rate yang membuat…",
o:[["NPV proyek sama dengan nol","Tepat. Pada r = IRR, PV arus kas masuk = biaya investasi, sehingga NPV = 0."],
["NPV proyek mencapai nilai maksimum","NPV maksimum terjadi pada discount rate serendah mungkin, bukan definisi IRR."],
["Payback period sama dengan umur proyek","Tidak ada hubungan definisi IRR dengan payback."],
["Nilai terminal arus kas sama dengan investasi awal","Ini mendekati konsep MIRR (terminal value), bukan IRR."]],
a:0,x:"IRR = discount rate yang membuat NPV = 0. IRR adalah estimasi return yang diharapkan dari proyek.\nAturan: jika IRR > biaya modal (WACC), NPV positif, kelebihannya menjadi \"bonus\" bagi pemegang saham dan nilai saham naik.\nDi Excel: =IRR(CF0:CFn)."},

{t:2,d:"e",
q:"Perusahaan Gong menilai Project S dan Project L (WACC 10%). Hasilnya: NPV S = $804,38; IRR S = 14,69%; NPV L = $1.048,02; IRR L = 13,79%. Jika kedua proyek bersifat mutually exclusive, proyek mana yang dipilih?",
o:[["Project S, karena IRR-nya lebih tinggi","Ini keputusan berbasis IRR. Materi menegaskan: bila konflik, putuskan dengan NPV."],
["Project L, karena NPV-nya lebih tinggi","Tepat. Untuk mutually exclusive, pilih NPV terbesar."],
["Keduanya, karena NPV keduanya positif","Mutually exclusive berarti hanya satu yang boleh dipilih. \"Keduanya\" hanya berlaku untuk proyek independen."],
["Tidak ada, karena NPV dan IRR saling bertentangan","Konflik NPV vs IRR diselesaikan dengan NPV, bukan dengan menolak keduanya."]],
a:1,x:"• Independen: S dan L bisa dijalankan dua-duanya selama NPV > 0.\n• Mutually exclusive: pilih satu. Berdasarkan NPV pilih L ($1.048 > $804), berdasarkan IRR pilih S (14,69% > 13,79%). Terjadi KONFLIK.\nPutuskan dengan NPV, karena NPV menggambarkan tambahan kas atau kekayaan yang dihasilkan. IRR lemah jika arus kas tidak normal.",
xl:{"s":["Ketik WACC di B1, lalu arus kas S di kolom B dan L di kolom C (baris 3–7).","NPV: =NPV($B$1;B4:B7)+B3. Fungsi NPV Excel menganggap sel pertama = tahun 1, jadi CF tahun 0 (B3) ditambahkan di luar fungsi.","IRR: =IRR(B3:B7), rentangnya termasuk tahun 0.","Salin rumus kolom B ke kolom C untuk Project L."],"g":[["WACC","10%"],["Tahun","Project S","Project L"],["0","-10000","-10000"],["1","5300","1900"],["2","4300","2700"],["3","1874","2345"],["4","1500","7800"],["NPV",{"f":"=NPV($B$1;B4:B7)+B3","v":"804,38"},{"f":"=NPV($B$1;C4:C7)+C3","v":"1.048,02"}],["IRR",{"f":"=IRR(B3:B7)","v":"14,69%"},{"f":"=IRR(C3:C7)","v":"13,79%"}]]}},

{t:2,d:"e",
q:"Sebuah proyek membutuhkan investasi awal $1.000 dan menghasilkan arus kas masuk $600 pada akhir tahun 1 dan $600 pada akhir tahun 2. Jika discount rate 10%, berapa NPV proyek?",
o:[["$200,00","Ini tanpa diskonto (600 + 600 − 1.000). Nilai waktu uang diabaikan."],
["$41,32","Tepat. 600/1,1 + 600/1,1² − 1.000 = 545,45 + 495,87 − 1.000 = 41,32."],
["$90,91","Kedua arus kas didiskonto dengan (1,1)¹, padahal arus kas tahun 2 harus dibagi (1,1)²."],
["$1.041,32","Ini PV arus kas masuk saja, belum dikurangi investasi awal."]],
a:1,x:"NPV = −1.000 + 600/(1,10)^1 + 600/(1,10)^2\n= −1.000 + 545,45 + 495,87\n= 41,32 → NPV > 0, proyek layak.\nExcel: =NPV(10%;600;600) − 1000 = 41,32.",
xl:{"s":["Ketik discount rate 10% di B1 dan arus kas di B3:B5 (tahun 0 bernilai negatif).","Cara cepat: B6 =NPV(B1;B4:B5)+B3. Tahun 1–2 masuk ke fungsi NPV, tahun 0 ditambahkan di luar.","Cara manual (untuk memahami): B7 =B3+B4/(1+B1)^A4+B5/(1+B1)^A5. Setiap arus kas DIBAGI (1 + r) pangkat tahunnya."],"g":[["Discount rate","10%"],["Tahun","Arus kas"],["0","-1000"],["1","600"],["2","600"],["NPV (fungsi)",{"f":"=NPV(B1;B4:B5)+B3","v":"41,32"}],["NPV (manual)",{"f":"=B3+B4/(1+B1)^A4+B5/(1+B1)^A5","v":"41,32"}]]}},

{t:2,d:"e",
q:"Project L memiliki arus kas: tahun 0 = −$10.000; tahun 1 = $1.900; tahun 2 = $2.700; tahun 3 = $2.345; tahun 4 = $7.800. Berapa payback period (regular payback) Project L?",
o:[["3,39 tahun","Tepat. Kumulatif akhir tahun 3 = −3.055, maka 3 + 3.055/7.800 = 3,39."],
["3,80 tahun","Ini discounted payback (memakai arus kas yang didiskonto)."],
["2,39 tahun","Pada akhir tahun 2 kumulatif masih −5.400, jadi belum balik modal."],
["3,61 tahun","Pecahan dihitung dari sisa yang salah (4.745/7.800 bukan 3.055/7.800)."]],
a:0,x:"Kumulatif arus kas: −10.000 → −8.100 → −5.400 → −3.055 → +4.745.\nModal kembali di tahun ke-4. Payback = 3 + (sisa yang belum kembali / arus kas tahun 4) = 3 + 3.055/7.800 = 3 + 0,39 = 3,39 tahun.\nKelemahan payback: mengabaikan nilai waktu uang dan arus kas setelah payback.",
xl:{"s":["Ketik tahun di kolom A dan arus kas di kolom B (baris 2–6).","C2 =B2 (kumulatif awal = arus kas tahun 0).","C3 =C2+B3, lalu tarik (drag) C3 ke bawah sampai C6. Setiap baris = kumulatif sebelumnya + arus kas tahun itu.","Cari baris TERAKHIR yang kumulatifnya masih negatif: tahun 3 (C5 = −3.055).","Payback = tahun itu + sisa yang belum kembali / arus kas tahun berikutnya: B8 =A5+ABS(C5)/B6."],"g":[["Tahun","Arus kas","Kumulatif"],["0","-10000",{"f":"=B2","v":"-10.000"}],["1","1900",{"f":"=C2+B3","v":"-8.100"}],["2","2700",{"f":"=C3+B4","v":"-5.400"}],["3","2345",{"f":"=C4+B5","v":"-3.055"}],["4","7800",{"f":"=C5+B6","v":"4.745"}],[],["Payback",{"f":"=A5+ABS(C5)/B6","v":"3,39"}]]}},

{t:2,d:"e",
q:"Sebuah proyek membutuhkan investasi awal $10.000. Nilai sekarang (PV) seluruh arus kas masuk masa depannya adalah $12.500. Berapa Profitability Index (PI) proyek?",
o:[["0,80","Ini terbalik: investasi dibagi PV arus masuk."],
["1,25","Tepat. PI = PV arus kas masuk / investasi awal = 12.500 / 10.000 = 1,25."],
["0,25","Ini NPV dibagi investasi (2.500/10.000), bukan PI."],
["2.500","Ini NPV dalam dolar, bukan indeks."]],
a:1,x:"PI = PV arus kas masa depan / investasi awal = 12.500/10.000 = 1,25.\nAturan: PI > 1 ⇔ NPV > 0 → terima. Contoh di materi: Project L PI = 11.048/10.000 = 1,10.",
xl:{"s":["B3 =B1/B2 (PV arus kas masuk dibagi investasi awal).","Cek: B4 =B1-B2 adalah NPV. PI > 1 selalu sejalan dengan NPV > 0."],"g":[["PV arus kas masuk","12500"],["Investasi awal","10000"],["PI",{"f":"=B1/B2","v":"1,25"}],["NPV",{"f":"=B1-B2","v":"2.500"}]]}},

{t:2,d:"e",
q:"Pola arus kas manakah yang termasuk NONNORMAL (tidak konvensional) sehingga berpotensi menghasilkan IRR lebih dari satu?",
o:[["− + + + + +","Hanya satu kali perubahan tanda, jadi normal."],
["− − − + + + +","Tetap satu kali perubahan tanda (dari − ke +), jadi normal."],
["− + + + + −","Tepat. Ada dua kali perubahan tanda (− ke + lalu + ke −), jadi nonnormal dan IRR bisa lebih dari satu."],
["− + + + + + +","Satu kali perubahan tanda, normal."]],
a:2,x:"Normal: tanda berubah hanya SEKALI (− + + + atau − − + + +).\nNonnormal: tanda berubah lebih dari sekali (− + + + − atau − + + − + +).\nArus kas nonnormal bisa menghasilkan lebih dari satu IRR. Contoh Project M (−1,6; +10; −10) punya IRR 25% DAN 400%. Ini salah satu alasan IRR tidak disarankan dan keputusan sebaiknya berdasarkan NPV."},

{t:2,d:"e",
q:"Apa kelebihan utama MIRR dibandingkan IRR menurut materi?",
o:[["MIRR selalu menghasilkan angka yang lebih tinggi dari IRR","Tidak benar. Bila WACC < IRR, MIRR justru lebih rendah dari IRR (contoh L: MIRR 12,78% < IRR 13,79%)."],
["MIRR dapat mengatasi arus kas tidak normal karena memakai satu terminal value","Tepat. Arus kas masuk dijadikan satu terminal value, sehingga hanya ada satu jawaban MIRR."],
["MIRR tidak memerlukan discount rate atau biaya modal sama sekali dalam perhitungannya","MIRR justru membutuhkan tingkat reinvestasi (biasanya WACC) untuk menghitung terminal value."],
["MIRR selalu memberi keputusan yang sama dengan regular payback period","Tidak ada hubungan seperti itu."]],
a:1,x:"Cara kerja MIRR:\n1. Majemukkan (compound) setiap arus kas masuk ke tahun terakhir (terminal year) dengan WACC.\n2. Jumlahkan semuanya menjadi Terminal Value (TV).\n3. Cari rate yang membuat PV biaya = TV/(1+MIRR)^n.\nKelebihannya: bisa mengatasi arus kas tidak normal (hanya satu MIRR).\nExcel: =MIRR(CF0:CFn; finance_rate; reinvest_rate)."},

{t:2,d:"e",
q:"Dalam menyusun arus kas proyek baru, manakah yang TIDAK boleh dimasukkan sebagai arus kas relevan (incremental cash flow)?",
o:[["Biaya survei pasar $50.000 yang sudah dibayar tahun lalu, apa pun keputusan proyeknya","Tepat. Ini sunk cost: sudah terjadi dan tidak berubah apa pun keputusannya, jadi bukan arus kas relevan."],
["Pendapatan sewa gedung yang hilang karena gedung milik perusahaan dipakai untuk proyek","Ini opportunity cost dan HARUS dimasukkan sebagai pengurang."],
["Penurunan penjualan produk lama akibat produk baru menggerus pasarnya sendiri","Ini kanibalisasi (externality negatif) dan HARUS dimasukkan."],
["Tambahan modal kerja (persediaan) yang dibutuhkan untuk menjalankan proyek","Perubahan NWC termasuk arus kas relevan."]],
a:0,x:"Incremental cash flow = arus kas perusahaan DENGAN proyek − arus kas perusahaan TANPA proyek.\nPertimbangan:\n• Sunk cost: biaya yang sudah terjadi, TIDAK dimasukkan.\n• Opportunity cost: manfaat yang hilang karena aset dipakai proyek, DIMASUKKAN.\n• Externalities (kanibalisasi atau komplementer): DIMASUKKAN.\n• Perubahan NWC: DIMASUKKAN."},

{t:2,d:"e",
q:"Peluncuran produk baru menyebabkan penjualan produk lama perusahaan yang sama menurun. Dalam capital budgeting, efek ini disebut…",
o:[["Positive within-firm externality (complementary)","Complementary = proyek baru justru menaikkan penjualan produk lain."],
["Negative within-firm externality (cannibalization)","Tepat. Kanibalisasi = proyek baru menggerus penjualan produk perusahaan sendiri."],
["Environmental externality","Environmental externality = dampak ke lingkungan sekitar."],
["Sunk cost","Sunk cost adalah biaya yang sudah terjadi, tidak terkait efek penjualan."]],
a:1,x:"Externalities = dampak proyek terhadap bagian lain perusahaan atau lingkungan:\n• Negative within-firm externalities = CANNIBALIZATION (dikurangkan dari arus kas proyek, after tax);\n• Positive within-firm externalities = COMPLEMENTARY (ditambahkan);\n• Environmental externalities."},

{t:2,d:"e",
q:"Mengapa depresiasi DITAMBAHKAN KEMBALI ketika menghitung arus kas operasional proyek dari laba (NOPAT)?",
o:[["Karena depresiasi merupakan arus kas masuk dari penjualan aset tetap di akhir proyek","Depresiasi bukan arus kas masuk. Penjualan aset dicatat sebagai salvage value."],
["Karena depresiasi adalah biaya noncash yang mengurangi pajak tanpa mengeluarkan kas","Tepat. Depresiasi melindungi laba dari pajak (tax shield), tetapi tidak ada kas yang keluar."],
["Karena depresiasi tidak boleh dikurangkan saat menghitung pajak penghasilan","Justru depresiasi dikurangkan saat menghitung pajak. Itu sebabnya ia menghemat pajak."],
["Karena depresiasi sama dengan pembelian aset sehingga harus dihitung dua kali","Pembelian aset dicatat sekali di tahun 0 (capital spending). Depresiasi bukan pembelian ulang."]],
a:1,x:"Pembelian aset = arus kas keluar di tahun 0. Akuntan tidak mencatatnya langsung sebagai beban, tetapi membebankan depresiasi setiap tahun.\nDepresiasi mengurangi EBIT sehingga pajak lebih kecil, tetapi depresiasi BUKAN arus kas riil. Maka:\nOCF = NOPAT + Depreciation = EBIT(1 − T) + Depreciation."},

{t:2,d:"e",
q:"Proyek L membutuhkan modal kerja sebesar 15% dari penjualan tahun berikutnya. Penjualan tahun 1 diperkirakan $15.000. Berapa investasi modal kerja (NWC) di tahun 0?",
o:[["$1.500","Ini 10%, bukan 15%."],
["$2.250","Tepat. 15% × $15.000 = $2.250."],
["$15.000","Ini nilai penjualan, bukan kebutuhan modal kerja."],
["$7.750","Ini biaya peralatan (equipment) Project L."]],
a:1,x:"Kebutuhan NWC tahun 0 = 15% × penjualan tahun 1 = 15% × 15.000 = $2.250.\nTotal arus kas keluar tahun 0 Project L = peralatan $7.750 + NWC $2.250 = $10.000.\nSetiap tahun yang dicatat adalah PERUBAHAN NWC (ΔNWC). Di tahun terakhir seluruh NWC kembali (recovery, arus kas +).",
xl:{"s":["Ketik 15% di B1 dan penjualan tahun 1 di B2.","B3 =B1*B2. Ini NWC yang harus disiapkan di tahun 0."],"g":[["NWC % penjualan berikutnya","15%"],["Penjualan tahun 1","15000"],["NWC tahun 0",{"f":"=B1*B2","v":"2.250"}]]}},

{t:2,d:"e",
q:"Dalam analisis sensitivitas Project L, deviasi ±30% menghasilkan range NPV: Equipment $3.102; Sales price $21.801; Units $6.095; VC/unit $15.706; Non-VC $2.521; WACC $1.794. Variabel yang PALING berisiko (paling sensitif) adalah…",
o:[["WACC (bobot risiko)","Range-nya justru terkecil ($1.794)."],
["Variable cost per unit","Range $15.706 besar, tetapi masih di bawah sales price."],
["Sales price per unit","Tepat. Range NPV-nya terbesar ($21.801), jadi paling sensitif atau berisiko."],
["Units sold","Range $6.095, jauh di bawah sales price."]],
a:2,x:"Sensitivity analysis mengukur perubahan NPV bila satu variabel input diubah (variabel lain tetap).\nRange = NPV tertinggi − NPV terendah. Range terbesar = paling berisiko. Inilah dasar Tornado Diagram (variabel diurutkan dari range terbesar).\nUrutan: Sales price (21.801) > VC/unit (15.706) > Units (6.095) > Equipment (3.102) > Non-VC (2.521) > WACC (1.794).\nJawaban tugas: \"Harga jual, karena selisih NPV-nya paling besar.\"",
xl:{"s":["Ketik nama variabel di kolom A dan range NPV di kolom B.","C2 =RANK(B2;$B$2:$B$7), lalu tarik ke bawah. Ranking 1 = range terbesar = paling berisiko (urutan teratas tornado diagram)."],"g":[["Variabel","Range NPV","Ranking"],["Equipment","3102",{"f":"=RANK(B2;$B$2:$B$7)","v":"4"}],["Sales price","21801",{"f":"=RANK(B3;$B$2:$B$7)","v":"1"}],["Units","6095",{"f":"=RANK(B4;$B$2:$B$7)","v":"3"}],["VC/unit","15706",{"f":"=RANK(B5;$B$2:$B$7)","v":"2"}],["Non-VC","2521",{"f":"=RANK(B6;$B$2:$B$7)","v":"5"}],["WACC","1794",{"f":"=RANK(B7;$B$2:$B$7)","v":"6"}]]}},

{t:2,d:"e",
q:"Berikut ini yang BUKAN teknik untuk mengukur stand-alone risk sebuah proyek menurut materi adalah…",
o:[["Sensitivity analysis","Termasuk teknik stand-alone risk."],
["Scenario analysis","Termasuk teknik stand-alone risk."],
["Monte Carlo simulation","Termasuk teknik stand-alone risk."],
["Payback period analysis","Benar, ini bukan teknik stand-alone risk. Payback adalah kriteria keputusan capital budgeting."]],
a:3,x:"Tiga jenis risiko proyek: Market risk, Within-firm risk, Stand-alone risk.\nStand-alone risk = ketidakpastian arus kas proyek itu sendiri (investasi awal, unit, harga, biaya bisa meleset).\nTeknik pengukurannya: (1) Sensitivity analysis, (2) Scenario analysis, (3) Monte Carlo simulation."},

{t:2,d:"e",
q:"Project C (umur 6 tahun) memiliki NPV $6.491. Project F (umur 3 tahun) memiliki NPV $5.155. Dengan common life approach (F diulang dua kali), NPV FF = $8.824. Jika keduanya mutually exclusive, keputusan yang tepat adalah…",
o:[["Pilih C, karena NPV satu kali C ($6.491) lebih besar dari NPV satu kali F ($5.155)","Membandingkan NPV proyek dengan umur berbeda secara langsung itu tidak adil. Umurnya harus disamakan dulu."],
["Pilih F (diulang), karena NPV FF ($8.824) lebih besar dari NPV C ($6.491)","Tepat. Setelah umur disamakan menjadi 6 tahun, F yang diulang memberi NPV lebih besar."],
["Pilih C, karena umur proyeknya lebih panjang sehingga menghasilkan arus kas lebih lama","Umur panjang tidak otomatis lebih baik. Bandingkan NPV pada umur yang sama."],
["Pilih F, karena IRR F (25,2%) lebih besar dari IRR C (17,5%)","Hasil akhirnya benar (F), tetapi alasannya salah. Untuk mutually exclusive dasar keputusan tetap NPV dengan umur yang disamakan."]],
a:1,x:"Mutually exclusive dengan umur berbeda tidak bisa dibandingkan langsung NPV-nya.\nCommon life (replacement chain): ulangi proyek pendek sampai umurnya sama. F (3 tahun) diulang 2 kali menjadi 6 tahun. Arus kas tahun 3 = 12.000 − 20.000 = −8.000.\nNPV FF = 5.155 + 5.155/(1,12)^3 = $8.824 > NPV C $6.491, maka pilih F.",
xl:{"s":["Ketik WACC di B1 dan NPV satu kali F di B2.","F kedua dimulai di akhir tahun 3, jadi NPV-nya didiskonto 3 tahun lagi: B3 =B2+B2/(1+B1)^3.","Bandingkan B3 dengan NPV C di B4. Yang lebih besar dipilih."],"g":[["WACC","12%"],["NPV F (3 tahun)","5155"],["NPV FF (6 tahun)",{"f":"=B2+B2/(1+B1)^3","v":"8.824,23"}],["NPV C (6 tahun)","6491"]]}},

/* ================= MATERI 2 · CAPITAL BUDGETING · HARD (15) ================= */
{t:2,d:"h",
q:"Project K: peralatan $12.000 (depresiasi tahun 1 = 33%), penjualan tahun 1 = 5.000 unit × $4,00, biaya variabel $2,40/unit, biaya tetap (non-VC) $3.000, pajak 25%. NWC = 10% dari penjualan tahun berikutnya. Penjualan tahun 2 diperkirakan $23.100. Berapa net cash flow proyek di TAHUN 1?",
o:[["$4.740","Ini OCF, belum dikurangi tambahan NWC tahun 1 (ΔNWC = $310)."],
["$4.430","Tepat. OCF 4.740 − ΔNWC 310 = 4.430."],
["$2.430","Ini mengurangkan seluruh saldo NWC ($2.310), padahal yang dikurangkan hanya perubahannya ($310)."],
["$470","Ini lupa menambahkan kembali depresiasi (780 − 310)."]],
a:1,x:"Revenue = 5.000 × 4 = 20.000\nVC = 5.000 × 2,40 = 12.000\nNon-VC = 3.000\nDepresiasi = 33% × 12.000 = 3.960\nEBIT = 20.000 − 12.000 − 3.000 − 3.960 = 1.040\nPajak 25% = 260 → NOPAT = 780\nOCF = NOPAT + depresiasi = 780 + 3.960 = 4.740\nNWC: saldo tahun 0 = 10% × 20.000 = 2.000; saldo tahun 1 = 10% × 23.100 = 2.310 → ΔNWC = 310 (outflow)\nNet CF tahun 1 = OCF − ΔNWC − capital spending = 4.740 − 310 − 0 = $4.430.\n(Format tugas: CF = OCF − NCS − ΔNWC.)",
xl:{"s":["Ketik semua input di B1:B9 (persen diketik dengan tanda %).","Revenue B11 =B3*B4; biaya variabel B12 =B3*B5; depresiasi B13 =B1*B2.","EBIT B14 =B11-B12-B6-B13; pajak B15 =B14*B7; NOPAT B16 =B14-B15.","OCF B17 =B16+B13. Depresiasi ditambahkan kembali karena noncash.","Saldo NWC: tahun 0 B18 =B8*B11 (10% × penjualan tahun 1), tahun 1 B19 =B8*B9 (10% × penjualan tahun 2). ΔNWC B20 =B19-B18.","Net CF tahun 1: B21 =B17-B20."],"g":[["Peralatan","12000"],["Tarif depresiasi tahun 1","33%"],["Unit terjual","5000"],["Harga/unit","4"],["Biaya variabel/unit","2,4"],["Biaya tetap","3000"],["Pajak","25%"],["NWC % penjualan berikutnya","10%"],["Penjualan tahun 2","23100"],[],["Revenue",{"f":"=B3*B4","v":"20.000"}],["Biaya variabel",{"f":"=B3*B5","v":"12.000"}],["Depresiasi",{"f":"=B1*B2","v":"3.960"}],["EBIT",{"f":"=B11-B12-B6-B13","v":"1.040"}],["Pajak",{"f":"=B14*B7","v":"260"}],["NOPAT",{"f":"=B14-B15","v":"780"}],["OCF",{"f":"=B16+B13","v":"4.740"}],["Saldo NWC tahun 0",{"f":"=B8*B11","v":"2.000"}],["Saldo NWC tahun 1",{"f":"=B8*B9","v":"2.310"}],["ΔNWC tahun 1",{"f":"=B19-B18","v":"310"}],["Net CF tahun 1",{"f":"=B17-B20","v":"4.430"}]]}},

{t:2,d:"h",
q:"Untuk proyek baru, perusahaan membeli mesin $12.000 dan membutuhkan NWC awal $2.000. Tahun lalu perusahaan sudah membayar studi kelayakan $800. Proyek akan memakai lahan milik perusahaan yang jika tidak dipakai bisa dijual dengan nilai setelah pajak $3.000. Berapa arus kas TAHUN 0?",
o:[["−$14.000","Ini lupa memasukkan opportunity cost lahan ($3.000)."],
["−$17.800","Ini ikut memasukkan studi kelayakan $800, padahal itu sunk cost."],
["−$17.000","Tepat. −12.000 − 2.000 − 3.000 = −17.000. Studi kelayakan diabaikan (sunk cost)."],
["−$14.800","Ini memasukkan sunk cost dan melupakan opportunity cost, dua kesalahan sekaligus."]],
a:2,x:"Arus kas tahun 0 = pembelian aset + NWC awal + opportunity cost (after tax).\n= −12.000 − 2.000 − 3.000 = −$17.000.\n• Studi kelayakan $800 = SUNK COST (sudah dibayar, tidak berubah apa pun keputusannya), jadi tidak dimasukkan.\n• Lahan yang bisa dijual $3.000 = OPPORTUNITY COST, jadi dimasukkan.\nDi tabel tugas: NCS tahun 0 = Equipment cost + Opportunity cost.",
xl:{"s":["Ketik semua biaya di kolom B. Studi kelayakan boleh ditulis sebagai catatan, tetapi JANGAN ikut dijumlahkan.","B5 =-(B1+B2+B3). Tanda minus karena semuanya arus kas keluar."],"g":[["Mesin","12000"],["NWC awal","2000"],["Opportunity cost lahan (after tax)","3000"],["Studi kelayakan (sunk cost, diabaikan)","800"],["Arus kas tahun 0",{"f":"=-(B1+B2+B3)","v":"-17.000"}]]}},

{t:2,d:"h",
q:"Di akhir umur proyek, peralatan dijual seharga $2.000. Nilai buku peralatan saat itu $500 dan tarif pajak 25%. Berapa arus kas after-tax salvage value?",
o:[["$2.000","Ini belum memperhitungkan pajak atas keuntungan penjualan aset."],
["$1.625","Tepat. 2.000 − 25% × (2.000 − 500) = 2.000 − 375 = 1.625."],
["$1.500","Ini pajak dihitung dari seluruh harga jual (2.000 × 75%)."],
["$1.875","Ini pajak dihitung dari nilai buku (25% × 500), bukan dari keuntungannya."]],
a:1,x:"After-tax salvage value = SV − (SV − Book Value) × T.\n= 2.000 − (2.000 − 500) × 25% = 2.000 − 375 = $1.625.\nRumus di Excel tugas: =B13 − (B13 − F44) × B25.\nContoh Project L: SV 639, nilai buku 0, pajak 40% → 639 − 256 = 383.",
xl:{"s":["B4 =(B1-B2)*B3. Pajak hanya dikenakan atas KEUNTUNGAN penjualan (harga jual − nilai buku).","B5 =B1-B4 adalah after-tax salvage value."],"g":[["Harga jual (SV)","2000"],["Nilai buku","500"],["Pajak","25%"],["Pajak atas keuntungan",{"f":"=(B1-B2)*B3","v":"375"}],["After-tax salvage",{"f":"=B1-B4","v":"1.625"}]]}},

{t:2,d:"h",
q:"Project K berumur 3 tahun. Data tahun 3: OCF $6.520,15. Saldo NWC akhir tahun 2 sebesar $2.668,05 dipulihkan seluruhnya di tahun 3. Peralatan dijual $1.500 dengan nilai buku $840 (pajak 25%). Berapa net cash flow TAHUN 3?",
o:[["$7.855,15","Ini belum memasukkan pemulihan NWC (+2.668,05)."],
["$10.688,20","Ini memakai salvage sebelum pajak ($1.500), seharusnya $1.335."],
["$10.523,20","Tepat. 6.520,15 + 2.668,05 + 1.335 = 10.523,20."],
["$9.188,20","Ini melupakan salvage value peralatan."]],
a:2,x:"After-tax salvage = 1.500 − (1.500 − 840) × 25% = 1.500 − 165 = 1.335.\nRecovery NWC tahun terakhir = +2.668,05 (seluruh modal kerja kembali).\nNet CF tahun 3 = OCF + recovery NWC + after-tax salvage\n= 6.520,15 + 2.668,05 + 1.335 = $10.523,20.\nDi tabel tugas: NCS tahun terakhir bernilai negatif (= −after-tax salvage) sehingga CF = OCF − NCS − ΔNWC menambahkannya. ΔNWC tahun terakhir juga negatif (recovery).",
xl:{"s":["Ketik OCF, recovery NWC, harga jual, nilai buku, dan pajak di B1:B5.","After-tax salvage: B6 =B3-(B3-B4)*B5.","Net CF tahun terakhir: B7 =B1+B2+B6 (OCF + modal kerja kembali + hasil jual aset setelah pajak)."],"g":[["OCF tahun 3","6520,15"],["Recovery NWC","2668,05"],["Harga jual peralatan","1500"],["Nilai buku","840"],["Pajak","25%"],["After-tax salvage",{"f":"=B3-(B3-B4)*B5","v":"1.335"}],["Net CF tahun 3",{"f":"=B1+B2+B6","v":"10.523,20"}]]}},

{t:2,d:"h",
q:"Seorang analis menyusun arus kas proyek dengan mengurangkan beban bunga pinjaman dari arus kas, lalu mendiskontonya dengan WACC. Apa akibatnya?",
o:[["NPV terlalu tinggi, karena bunga mengurangi pajak sehingga arus kas bertambah","Efeknya justru kebalikannya: biaya pendanaan terhitung dua kali sehingga NPV terlalu rendah."],
["NPV terlalu rendah, karena biaya pendanaan dihitung dua kali (di arus kas dan di WACC)","Tepat. Biaya utang (setelah pajak) sudah ada di WACC. Mengurangkan bunga lagi berarti double counting."],
["NPV tetap benar, karena bunga merupakan beban tunai yang memang dibayar perusahaan","Bunga memang beban tunai, tetapi dalam capital budgeting biaya pendanaan ditangkap lewat discount rate (WACC), bukan arus kas."],
["NPV tidak terpengaruh, karena bunga hanya memengaruhi laba bersih, tidak memengaruhi arus kas","Mengurangkan bunga dari arus kas jelas mengubah arus kas sehingga NPV berubah."]],
a:1,x:"Materi: \"Beban Bunga vs Discount Rate\". Bunga adalah kompensasi atas penggunaan dana. Dalam capital budgeting, biaya pendanaan (utang dan ekuitas) sudah tercermin dalam WACC sebagai discount rate.\nKarena itu arus kas proyek dihitung dari EBIT (sebelum bunga): OCF = EBIT(1 − T) + Depresiasi.\nJika bunga dikurangkan lagi, biaya pendanaan terhitung DUA KALI, sehingga NPV understated."},

{t:2,d:"h",
q:"Project S: IRR 14,69%. Project L: IRR 13,79%. Crossover rate kedua proyek = 12,27%. Pada WACC 13%, NPV S = $276,55 dan NPV L = $205,00. Jika mutually exclusive dan WACC 13%, pernyataan yang benar adalah…",
o:[["Pilih L, karena di bawah crossover rate L selalu memiliki NPV lebih besar","13% berada DI ATAS crossover (12,27%), bukan di bawah. Di atas crossover, S memiliki NPV lebih besar."],
["Pilih S, dan tidak ada konflik karena NPV maupun IRR S lebih besar","Tepat. Di atas crossover, NPV S > NPV L dan IRR S > IRR L, sehingga keduanya sepakat memilih S."],
["Pilih S, tetapi terjadi konflik karena NPV L lebih besar dari NPV S","Pada 13%, NPV S ($276,55) > NPV L ($205,00). Tidak ada konflik."],
["Tolak keduanya, karena WACC 13% sudah melebihi IRR kedua proyek","IRR S (14,69%) dan IRR L (13,79%) masih di atas 13%, sehingga NPV keduanya positif."]],
a:1,x:"Profil NPV S dan L berpotongan di crossover rate 12,27% (IRR dari selisih arus kas S − L).\n• WACC < 12,27%: NPV L > NPV S, sedangkan IRR S > IRR L, jadi KONFLIK (pilih L berdasarkan NPV).\n• WACC > 12,27%: NPV S > NPV L dan IRR S > IRR L, jadi TIDAK ADA konflik (pilih S).\nCatatan: di slide tertulis 12,2475%. Setelah dihitung ulang, IRR selisih arus kas = 12,274%.",
xl:{"s":["Ketik WACC 13% di B1 dan arus kas S, L di kolom B, C (baris 3–7).","Kolom D = selisih S − L: D3 =B3-C3, tarik ke bawah sampai D7.","NPV tiap proyek pada 13%: B8 =NPV($B$1;B4:B7)+B3, salin ke C8.","Crossover = IRR dari selisih: D9 =IRR(D3:D7)."],"g":[["WACC","13%"],["Tahun","S","L","S − L"],["0","-10000","-10000",{"f":"=B3-C3","v":"0"}],["1","5300","1900",{"f":"=B4-C4","v":"3.400"}],["2","4300","2700",{"f":"=B5-C5","v":"1.600"}],["3","1874","2345",{"f":"=B6-C6","v":"-471"}],["4","1500","7800",{"f":"=B7-C7","v":"-6.300"}],["NPV",{"f":"=NPV($B$1;B4:B7)+B3","v":"276,55"},{"f":"=NPV($B$1;C4:C7)+C3","v":"205,00"}],["IRR",{"f":"=IRR(B3:B7)","v":"14,69%"},{"f":"=IRR(C3:C7)","v":"13,79%"},{"f":"=IRR(D3:D7)","v":"12,27%"}]]}},

{t:2,d:"h",
q:"Dua proyek mutually exclusive berikut memiliki investasi yang sama. Hitung crossover rate keduanya, lalu tentukan proyek yang dipilih bila WACC = 6%.",
tb:[["Tahun","0","1","2","3"],["Proyek A","−5.000","3.000","2.500","1.000"],["Proyek B","−5.000","500","2.000","4.500"]],
o:[["Crossover 8,74%; pilih B","Tepat. Pada WACC 6% (di bawah crossover), proyek dengan arus kas di belakang (B) memiliki NPV lebih besar."],
["Crossover 8,74%; pilih A","Crossover-nya benar, tetapi pada 6% (di bawah crossover) NPV B > NPV A. A lebih unggul hanya di atas 8,74%."],
["Crossover 17,21%; pilih A","17,21% adalah IRR A, bukan crossover rate."],
["Crossover 14,13%; pilih B","14,13% adalah IRR B, bukan crossover rate."]],
a:0,x:"Crossover = IRR dari selisih arus kas (A − B):\nTahun 0: 0; tahun 1: 2.500; tahun 2: 500; tahun 3: −3.500.\nExcel: ketik selisih arus kas di satu baris (0; 2.500; 500; −3.500) lalu =IRR(rentang itu) = 8,74%.\nCek: NPV pada 0% → A = 1.500, B = 2.000 (B lebih tinggi). Arus kas B terkonsentrasi di akhir sehingga lebih sensitif terhadap discount rate (garis profil lebih curam).\nWACC 6% < 8,74%, maka NPV B > NPV A. Pilih B (walaupun IRR A lebih tinggi, inilah konflik NPV vs IRR).",
xl:{"s":["Ketik arus kas A di kolom B dan B di kolom C (baris 2–5).","Kolom D = selisih A − B: D2 =B2-C2, tarik ke bawah sampai D5.","Crossover: D8 =IRR(D2:D5). IRR masing-masing proyek: B8 =IRR(B2:B5), C8 =IRR(C2:C5).","Ketik WACC 6% di B6, lalu B7 =NPV($B$6;B3:B5)+B2 dan salin ke C7. NPV yang lebih besar dipilih."],"g":[["Tahun","Proyek A","Proyek B","Selisih A − B"],["0","-5000","-5000",{"f":"=B2-C2","v":"0"}],["1","3000","500",{"f":"=B3-C3","v":"2.500"}],["2","2500","2000",{"f":"=B4-C4","v":"500"}],["3","1000","4500",{"f":"=B5-C5","v":"-3.500"}],["WACC","6%"],["NPV pada WACC",{"f":"=NPV($B$6;B3:B5)+B2","v":"894,80"},{"f":"=NPV($B$6;C3:C5)+C2","v":"1.029,98"}],["IRR",{"f":"=IRR(B2:B5)","v":"17,21%"},{"f":"=IRR(C2:C5)","v":"14,13%"},{"f":"=IRR(D2:D5)","v":"8,74%"}]]}},

{t:2,d:"h",
q:"Sebuah proyek memiliki arus kas: tahun 0 = −$8.000; tahun 1 = $3.000; tahun 2 = $4.000; tahun 3 = $4.000. WACC (dan tingkat reinvestasi) = 10%. Berapa MIRR proyek?",
o:[["16,88%","Ini IRR biasa, bukan MIRR."],
["14,57%","Tepat. TV = 3.000(1,1)² + 4.000(1,1) + 4.000 = 12.030; MIRR = (12.030/8.000)^(1/3) − 1 = 14,57%."],
["12,03%","Ini salah membaca TV (12.030) sebagai persentase."],
["10,74%","Pangkatnya salah: memakai n = 4 (jumlah kolom), padahal umur proyek n = 3 tahun."]],
a:1,x:"Langkah MIRR:\n1. Compound arus kas masuk ke tahun 3 dengan 10%:\n 3.000 × 1,1² = 3.630\n 4.000 × 1,1¹ = 4.400\n 4.000 × 1,1⁰ = 4.000\n TV = 12.030\n2. PV biaya = 8.000\n3. 8.000 = 12.030/(1 + MIRR)³ → MIRR = (12.030/8.000)^(1/3) − 1 = 14,57%.\nExcel: =MIRR(−8000;3000;4000;4000; 10%; 10%) = 14,57%. Bandingkan: IRR = 16,88%. MIRR < IRR karena reinvestasi diasumsikan pada WACC (10%), bukan pada IRR.",
xl:{"s":["MIRR memakai COMPOUNDING (dikali), kebalikan dari diskonto (dibagi). Setiap arus kas masuk \"dibawa maju\" ke tahun terakhir (tahun 3).","Kolom C = berapa tahun lagi sampai tahun 3: C4 =$A$6-A4, tarik ke bawah (hasil 2, 1, 0).","Kolom D = nilai di tahun 3: D4 =B4*(1+$B$1)^C4, tarik ke bawah. Tanda $ mengunci B1 (WACC) dan A6 (tahun terakhir) saat rumus ditarik.","Terminal Value: D7 =SUM(D4:D6).","MIRR manual: B8 =(D7/-B3)^(1/A6)-1, yaitu (TV / investasi)^(1/n) − 1.","Cek dengan fungsi Excel: B9 =MIRR(B3:B6;B1;B1). Argumen kedua = finance rate, ketiga = reinvestment rate (keduanya WACC)."],"g":[["WACC","10%"],["Tahun","Arus kas","Pangkat (3 − t)","Nilai di tahun 3"],["0","-8000"],["1","3000",{"f":"=$A$6-A4","v":"2"},{"f":"=B4*(1+$B$1)^C4","v":"3.630"}],["2","4000",{"f":"=$A$6-A5","v":"1"},{"f":"=B5*(1+$B$1)^C5","v":"4.400"}],["3","4000",{"f":"=$A$6-A6","v":"0"},{"f":"=B6*(1+$B$1)^C6","v":"4.000"}],["Terminal Value","","",{"f":"=SUM(D4:D6)","v":"12.030"}],["MIRR manual",{"f":"=(D7/-B3)^(1/A6)-1","v":"14,57%"}],["MIRR fungsi",{"f":"=MIRR(B3:B6;B1;B1)","v":"14,57%"}],["IRR (pembanding)",{"f":"=IRR(B3:B6)","v":"16,88%"}]]}},

{t:2,d:"h",
q:"Sebuah proyek memiliki arus kas: tahun 0 = −$6.000; tahun 1 = $2.000; tahun 2 = $2.500; tahun 3 = $3.000; tahun 4 = $1.500. Dengan discount rate 10%, berapa DISCOUNTED payback period-nya?",
o:[["2,50 tahun","Ini regular payback (tanpa diskonto): 2 + 1.500/3.000."],
["2,94 tahun","Tepat. Kumulatif PV akhir tahun 2 = −2.115,70; PV tahun 3 = 2.253,94; maka 2 + 2.115,70/2.253,94 = 2,94."],
["2,67 tahun","Ini mencampur sisa kumulatif TANPA diskonto (1.500) dengan PV tahun 3 (2.253,94)."],
["2,71 tahun","Sisa PV (2.115,70) dibagi arus kas tahun 3 yang belum didiskonto (3.000). Pembaginya harus PV 2.253,94."]],
a:1,x:"Discounted payback = payback biasa, tetapi setiap arus kas DIDISKONTO dulu ke nilai sekarang (PV). Diskonto artinya DIBAGI (1 + r)^t. Ini kebalikan dari compounding (DIKALI (1 + r)^t) yang dipakai di MIRR.\n\nLangkah 1, ubah setiap arus kas menjadi PV: PV = CF / (1 + 10%)^tahun.\nTahun 1: 2.000 / 1,1¹ = 2.000 / 1,1 = 1.818,18\nTahun 2: 2.500 / 1,1² = 2.500 / 1,21 = 2.066,12\nTahun 3: 3.000 / 1,1³ = 3.000 / 1,331 = 2.253,94\nTahun 4: 1.500 / 1,1⁴ = 1.500 / 1,4641 = 1.024,52\n\nLangkah 2, jumlahkan PV secara kumulatif mulai dari −6.000:\nAkhir tahun 1: −6.000 + 1.818,18 = −4.181,82\nAkhir tahun 2: −4.181,82 + 2.066,12 = −2.115,70 (masih negatif)\nAkhir tahun 3: −2.115,70 + 2.253,94 = +138,24 (sudah positif, modal kembali di tahun 3)\n\nLangkah 3, hitung pecahan tahun: dari PV tahun 3 (2.253,94), yang dibutuhkan hanya 2.115,70 untuk menutup sisa.\nPecahan = 2.115,70 / 2.253,94 = 0,94 → discounted payback = 2 + 0,94 = 2,94 tahun.\n\nDiscounted payback selalu lebih lama dari regular payback (2,50 tahun) karena arus kas mengecil setelah didiskonto.",
xl:{"s":["Ketik discount rate 10% di B1, lalu tahun di kolom A dan arus kas di kolom B (baris 3–7).","Faktor diskonto (kolom C): C3 =1/(1+$B$1)^A3, lalu tarik ke bawah sampai C7. Artinya \"1 dibagi 1,1 pangkat tahun\": tahun 1 = 0,9091, tahun 2 = 0,8264, dan seterusnya. Tanda $ di $B$1 membuat rumus tetap merujuk ke sel rate saat ditarik.","PV arus kas (kolom D): D3 =B3*C3, tarik ke bawah. Ini sama dengan =B3/(1+$B$1)^A3.","Kumulatif PV (kolom E): E3 =D3, lalu E4 =E3+D4 dan tarik sampai E7.","Cari baris TERAKHIR yang kumulatif PV-nya masih negatif: tahun 2 (E5 = −2.115,70). Modal kembali di tahun 3.","Discounted payback: B9 =A5+ABS(E5)/D6, yaitu tahun 2 + sisa PV yang belum kembali / PV tahun 3."],"g":[["Discount rate","10%"],["Tahun","Arus kas","Faktor diskonto","PV arus kas","Kumulatif PV"],["0","-6000",{"f":"=1/(1+$B$1)^A3","v":"1,0000"},{"f":"=B3*C3","v":"-6.000"},{"f":"=D3","v":"-6.000"}],["1","2000",{"f":"=1/(1+$B$1)^A4","v":"0,9091"},{"f":"=B4*C4","v":"1.818,18"},{"f":"=E3+D4","v":"-4.181,82"}],["2","2500",{"f":"=1/(1+$B$1)^A5","v":"0,8264"},{"f":"=B5*C5","v":"2.066,12"},{"f":"=E4+D5","v":"-2.115,70"}],["3","3000",{"f":"=1/(1+$B$1)^A6","v":"0,7513"},{"f":"=B6*C6","v":"2.253,94"},{"f":"=E5+D6","v":"138,24"}],["4","1500",{"f":"=1/(1+$B$1)^A7","v":"0,6830"},{"f":"=B7*C7","v":"1.024,52"},{"f":"=E6+D7","v":"1.162,76"}],[],["Discounted payback",{"f":"=A5+ABS(E5)/D6","v":"2,94"}]]}},

{t:2,d:"h",
q:"Tabel sensitivitas Project L (deviasi dari base case):\n• −30%: Equipment $2.599 | Price −$9.852 | Units −$1.999 | VC/unit $8.901 | Non-VC $2.309 | WACC $1.999\n• +30%: Equipment −$503 | Price $11.949 | Units $4.096 | VC/unit −$6.805 | Non-VC −$213 | WACC $205\nPernyataan yang BENAR adalah…",
o:[["VC/unit memiliki slope positif dan berada di urutan kedua tornado diagram","Urutan kedua benar (range 15.706), tetapi slope VC NEGATIF: VC naik, NPV turun."],
["Units sold berada di urutan kedua tornado diagram dengan range $6.095","Range Units ($6.095) berada di urutan ketiga, di bawah Price dan VC/unit."],
["VC/unit memiliki slope negatif dengan range $15.706, urutan kedua setelah sales price","Tepat. VC naik 30% membuat NPV turun ke −6.805, dan range-nya 8.901 − (−6.805) = 15.706."],
["Equipment memiliki slope positif karena harga peralatan yang naik menambah depresiasi","Equipment naik membuat NPV turun (2.599 → −503), jadi slope-nya negatif."]],
a:2,x:"Range = |NPV(+30%) − NPV(−30%)|:\nPrice: 11.949 − (−9.852) = 21.801 (1)\nVC/unit: 8.901 − (−6.805) = 15.706 (2)\nUnits: 4.096 − (−1.999) = 6.095 (3)\nEquipment: 3.102 (4); Non-VC: 2.521 (5); WACC: 1.794 (6).\nSlope positif (variabel naik, NPV naik): Price, Units. Slope negatif: VC/unit, Non-VC, Equipment, WACC.\nTornado diagram: sumbu Y = ranking variabel, sumbu X = range NPV.",
xl:{"s":["Ketik NPV −30% di kolom B dan NPV +30% di kolom C.","Range: D2 =ABS(C2-B2), tarik ke bawah.","Ranking: E2 =RANK(D2;$D$2:$D$7), tarik ke bawah (1 = paling sensitif).","Arah slope: F2 =IF(C2>B2;\"positif\";\"negatif\"). Positif berarti variabel naik membuat NPV naik."],"g":[["Variabel","NPV −30%","NPV +30%","Range","Ranking","Slope"],["Equipment","2599","-503",{"f":"=ABS(C2-B2)","v":"3.102"},{"f":"=RANK(D2;$D$2:$D$7)","v":"4"},{"f":"=IF(C2>B2;\"positif\";\"negatif\")","v":"negatif"}],["Price","-9852","11949",{"f":"=ABS(C3-B3)","v":"21.801"},{"f":"=RANK(D3;$D$2:$D$7)","v":"1"},{"f":"=IF(C3>B3;\"positif\";\"negatif\")","v":"positif"}],["Units","-1999","4096",{"f":"=ABS(C4-B4)","v":"6.095"},{"f":"=RANK(D4;$D$2:$D$7)","v":"3"},{"f":"=IF(C4>B4;\"positif\";\"negatif\")","v":"positif"}],["VC/unit","8901","-6805",{"f":"=ABS(C5-B5)","v":"15.706"},{"f":"=RANK(D5;$D$2:$D$7)","v":"2"},{"f":"=IF(C5>B5;\"positif\";\"negatif\")","v":"negatif"}],["Non-VC","2309","-213",{"f":"=ABS(C6-B6)","v":"2.522"},{"f":"=RANK(D6;$D$2:$D$7)","v":"5"},{"f":"=IF(C6>B6;\"positif\";\"negatif\")","v":"negatif"}],["WACC","1999","205",{"f":"=ABS(C7-B7)","v":"1.794"},{"f":"=RANK(D7;$D$2:$D$7)","v":"6"},{"f":"=IF(C7>B7;\"positif\";\"negatif\")","v":"negatif"}]]}},

{t:2,d:"h",
q:"Dalam analisis sensitivitas Project L (base WACC 10%), skenario \"bobot risiko/WACC +30%\" dihitung ulang. Discount rate yang dipakai dan perkiraan NPV-nya adalah…",
o:[["40%; NPV sangat negatif","Ini salah membaca +30% sebagai +30 poin persentase (10% + 30%). Deviasi ±30% adalah perubahan relatif dari base."],
["13%; NPV sekitar $205","Tepat. 10% × (1 + 30%) = 13%, dan NPV L pada 13% ≈ $205."],
["13%; NPV sekitar $1.999","$1.999 adalah NPV untuk WACC −30% (yaitu 7%), bukan +30%."],
["7%; NPV sekitar $205","7% adalah skenario WACC −30%, dan NPV-nya sekitar $1.999, bukan $205."]],
a:1,x:"Deviasi dari base dihitung relatif: nilai baru = base × (1 + deviasi).\nWACC +30% = 10% × 1,3 = 13%, NPV ≈ $205.\nWACC −30% = 10% × 0,7 = 7%, NPV ≈ $1.999.\nRumus di Excel tugas: =NPV(B24*(1+B63); CF1:CF4) + CF0.\nCara yang sama untuk harga: $1,50 × (1 − 30%) = $1,05 dan $1,50 × 1,3 = $1,95.",
xl:{"s":["Ketik WACC base 10% di B1 dan deviasi 30% di B2.","WACC baru: B3 =B1*(1+B2). Hasilnya 13%, bukan 40%, karena deviasi bersifat relatif terhadap base.","Ketik arus kas Project L di B5:B9.","NPV +30%: B10 =NPV(B3;B6:B9)+B5. NPV −30%: B11 =NPV(B1*(1-B2);B6:B9)+B5."],"g":[["WACC base","10%"],["Deviasi","30%"],["WACC +30%",{"f":"=B1*(1+B2)","v":"13,00%"}],["Tahun","Arus kas L"],["0","-10000"],["1","1900"],["2","2700"],["3","2345"],["4","7800"],["NPV (WACC +30%)",{"f":"=NPV(B3;B6:B9)+B5","v":"205,00"}],["NPV (WACC −30%)",{"f":"=NPV(B1*(1-B2);B6:B9)+B5","v":"1.998,79"}]]}},

{t:2,d:"h",
q:"Proyek X (umur 2 tahun): −$10.000; $6.500; $6.500. Proyek Y (umur 4 tahun) memiliki NPV $2.000. WACC 10%, keduanya mutually exclusive, dan X bisa diulang dengan arus kas yang sama. Berdasarkan common life approach, keputusan yang tepat adalah…",
o:[["Pilih Y, karena NPV Y ($2.000) lebih besar dari NPV X ($1.281)","Membandingkan NPV pada umur yang berbeda itu tidak tepat. X harus diulang dulu menjadi 4 tahun."],
["Pilih X, karena NPV XX (4 tahun) ≈ $2.340 > $2.000","Tepat. NPV XX = 1.281 + 1.281/1,1² = 2.340."],
["Pilih X, karena NPV XX = 2 × $1.281 = $2.562","Pilihan X benar, tetapi angkanya salah: NPV putaran kedua harus didiskonto 2 tahun lagi."],
["Pilih Y, karena NPV XX ≈ $1.940 < $2.000","Angka ini keliru. NPV XX yang benar ≈ $2.340."]],
a:1,x:"NPV X = −10.000 + 6.500/1,1 + 6.500/1,1² = $1.280,99.\nX diulang (XX) selama 4 tahun: arus kas tahun 2 = 6.500 − 10.000 = −3.500.\nNPV XX = 1.280,99 + 1.280,99/(1,1)² = 1.280,99 + 1.058,67 = $2.339,66.\nKarena 2.339,66 > 2.000, pilih X.\nPerangkap: menjumlahkan 2 × 1.281 tanpa mendiskonto putaran kedua.",
xl:{"s":["Ketik WACC di B1. Kolom B = X sekali jalan, kolom C = X diulang (XX) selama 4 tahun.","Tahun 2 XX = 6.500 − 10.000 = −3.500, karena X kedua dibeli di akhir tahun 2.","NPV X: B8 =NPV($B$1;B4:B7)+B3. NPV XX: C8 =NPV($B$1;C4:C7)+C3.","Cara cepat tanpa tabel XX: B9 =B8+B8/(1+B1)^2 (NPV X kedua didiskonto 2 tahun)."],"g":[["WACC","10%"],["Tahun","X","XX (diulang)"],["0","-10000","-10000"],["1","6500","6500"],["2","6500","-3500"],["3","","6500"],["4","","6500"],["NPV",{"f":"=NPV($B$1;B4:B7)+B3","v":"1.280,99"},{"f":"=NPV($B$1;C4:C7)+C3","v":"2.339,66"}],["NPV XX (cara cepat)",{"f":"=B8+B8/(1+B1)^2","v":"2.339,66"}]]}},

{t:2,d:"h",
q:"Arus kas operasional tahunan proyek baru (sebelum memperhitungkan efek lain) adalah $3.000. Peluncuran proyek akan menurunkan laba sebelum pajak produk lama sebesar $800 per tahun. Tarif pajak 25%. Berapa arus kas tahunan proyek yang relevan?",
o:[["$2.200","Ini mengurangkan kanibalisasi sebelum pajak. Seharusnya after tax (800 × 75% = 600)."],
["$2.400","Tepat. Kanibalisasi after tax = 800 × (1 − 25%) = 600; 3.000 − 600 = 2.400."],
["$3.600","Kanibalisasi adalah externality NEGATIF, jadi dikurangkan, bukan ditambahkan."],
["$3.000","Kanibalisasi tidak boleh diabaikan karena termasuk incremental cash flow."]],
a:1,x:"Kanibalisasi = negative within-firm externality, dimasukkan setelah pajak (after taxes) sebagai pengurang.\nEfek after tax = 800 × (1 − 0,25) = 600.\nArus kas relevan = 3.000 − 600 = $2.400.\nDi template materi: \"Cannibalization or complementary effects, after taxes (+/−)\".",
xl:{"s":["B4 =B2*(1-B3) adalah efek kanibalisasi setelah pajak.","B5 =B1-B4 adalah arus kas relevan."],"g":[["Arus kas operasional proyek","3000"],["Kanibalisasi (sebelum pajak)","800"],["Pajak","25%"],["Kanibalisasi after tax",{"f":"=B2*(1-B3)","v":"600"}],["Arus kas relevan",{"f":"=B1-B4","v":"2.400"}]]}},

{t:2,d:"h",
q:"Project M memiliki arus kas (dalam juta): tahun 0 = −1,6; tahun 1 = +10; tahun 2 = −10. IRR-nya 25% dan 400%. Jika WACC perusahaan 10%, keputusan yang tepat adalah…",
o:[["Terima, karena kedua IRR (25% dan 400%) lebih besar dari WACC 10%","Aturan IRR tidak berlaku pada arus kas nonnormal. NPV pada 10% justru negatif."],
["Tolak, karena NPV pada WACC 10% ≈ −0,77 juta (negatif)","Tepat. NPV = −1,6 + 10/1,1 − 10/1,21 = −0,77. Keputusan mengikuti NPV."],
["Terima, karena IRR yang dipakai adalah IRR terbesar, yaitu 400%","Tidak ada aturan memilih IRR terbesar. Arus kas nonnormal membuat IRR tidak bisa diandalkan."],
["Tolak, karena IRR terkecil (25%) lebih kecil dari WACC 10%","25% justru lebih besar dari 10%. Keputusan menolak benar, tetapi alasannya salah."]],
a:1,x:"Arus kas − + − adalah NONNORMAL (dua kali ganti tanda), sehingga IRR ganda: 25% dan 400%.\nProfil NPV: r = 0% → −1,6; antara 25% dan 400% NPV positif; di luar rentang itu negatif.\nNPV pada 10% = −1,6 + 10/1,1 − 10/1,1² = −1,6 + 9,091 − 8,264 = −0,77 (negatif). Proyek DITOLAK.\nPelajaran: untuk arus kas nonnormal, jangan memakai IRR. Gunakan NPV (atau MIRR).",
xl:{"s":["Ketik WACC di B1 dan arus kas di B3:B5. Desimal di Excel regional Indonesia diketik dengan koma: −1,6.","NPV: B6 =NPV(B1;B4:B5)+B3, hasilnya negatif sehingga proyek ditolak.","IRR ganda: fungsi IRR bisa diberi tebakan (guess) di argumen kedua. B7 =IRR(B3:B5;10%) menemukan 25%, B8 =IRR(B3:B5;300%) menemukan 400%."],"g":[["WACC","10%"],["Tahun","Arus kas (juta)"],["0","-1,6"],["1","10"],["2","-10"],["NPV",{"f":"=NPV(B1;B4:B5)+B3","v":"-0,77"}],["IRR (tebakan 10%)",{"f":"=IRR(B3:B5;10%)","v":"25,00%"}],["IRR (tebakan 300%)",{"f":"=IRR(B3:B5;300%)","v":"400,00%"}]]}},

{t:2,d:"h",
q:"Perusahaan mengganti metode depresiasi peralatan proyek dari garis lurus menjadi depresiasi dipercepat (accelerated). Total depresiasi selama umur proyek dan semua variabel lain tetap sama. Apa dampaknya terhadap NPV proyek?",
o:[["NPV naik, karena penghematan pajak (tax shield) diterima lebih awal sehingga PV-nya lebih besar","Tepat. Total tax shield sama, tetapi diterima lebih cepat, jadi nilai sekarangnya lebih tinggi."],
["NPV turun, karena laba bersih tahun-tahun awal menjadi lebih kecil akibat depresiasi yang lebih besar","Laba akuntansi memang turun di awal, tetapi capital budgeting melihat arus kas. Pajak lebih kecil di awal berarti arus kas lebih besar."],
["NPV tidak berubah, karena total depresiasi selama umur proyek sama besarnya","Waktu penerimaan arus kas penting (nilai waktu uang). Distribusi tax shield yang berbeda mengubah PV."],
["NPV tidak berubah, karena depresiasi adalah biaya noncash sehingga tidak memengaruhi arus kas","Depresiasi memang noncash, tetapi memengaruhi pajak yang dibayar (tunai)."]],
a:0,x:"Depresiasi tidak mengeluarkan kas, tetapi mengurangi pajak: tax shield = Depresiasi × T.\nDengan accelerated depreciation (seperti Project L: 33%, 45%, 15%, 7%), tax shield lebih besar di tahun-tahun awal. Totalnya sama, tetapi karena diterima lebih cepat, PV-nya lebih besar, jadi NPV naik.\nIni sesuai prinsip materi pengantar: semakin cepat arus kas diterima, semakin baik (salah satu tujuan pembelajaran Capital Budgeting Part 2: dampak usia penyusutan terhadap NPV)."},

/* ================= MATERI 3 · COST OF CAPITAL · EASY (15) ================= */
{t:3,d:"e",
q:"Cost of capital menggambarkan…",
o:[["Biaya keseluruhan pendanaan perusahaan dari utang, saham preferen, dan saham biasa","Tepat. Cost of capital adalah biaya keseluruhan pendanaan (overall cost of financing)."],
["Total bunga yang dibayar perusahaan kepada bank selama satu tahun","Ini hanya sebagian dari biaya utang, belum mencakup ekuitas dan saham preferen."],
["Total dividen tunai yang dibagikan kepada seluruh pemegang saham biasa setiap tahun","Dividen bukan ukuran cost of capital secara keseluruhan."],
["Harga pasar saham perusahaan dibagi laba bersih per lembar saham (EPS)","Ini rasio P/E, bukan cost of capital."]],
a:0,x:"Kebanyakan perusahaan mendanai diri dengan kombinasi common equity, preferred stock, dan debt.\nCost of capital = overall cost of financing perusahaan, biasanya diukur dengan WACC.\nCost of capital juga merupakan required return investor: imbal hasil minimum yang harus dihasilkan perusahaan."},

{t:3,d:"e",
q:"Berikut ini yang BUKAN merupakan alasan pentingnya cost of capital menurut materi adalah…",
o:[["Investment evaluation, karena menjadi discount rate yang relevan untuk menilai investasi","Termasuk alasan di materi."],
["Optimal financing mix, karena membantu menemukan kombinasi dana dengan biaya terendah","Termasuk alasan di materi."],
["Risk indicator, karena menunjukkan bagaimana pasar memandang risiko aset perusahaan","Termasuk alasan di materi."],
["Tax avoidance, karena memungkinkan perusahaan membayar pajak lebih kecil setiap tahun","Benar, ini bukan alasan di materi. Penghematan pajak hanya karakteristik utang, bukan fungsi cost of capital."]],
a:3,x:"Tiga kegunaan cost of capital:\n1. Investment Evaluation: discount rate yang relevan untuk analisis investasi (NPV di capital budgeting).\n2. Optimal Financing Mix: mencari kombinasi dana dengan biaya terendah.\n3. Risk Indicator: menunjukkan bagaimana pasar memandang risiko aset perusahaan."},

{t:3,d:"e",
q:"Manakah pernyataan yang BENAR mengenai cost of debt?",
o:[["Cost of debt sama dengan coupon rate yang tercantum pada obligasi perusahaan","Materi menegaskan: \"The cost of debt is NOT the coupon rate\"."],
["Cost of debt adalah required return kreditor, yaitu YTM atau bunga pinjaman baru","Tepat. Biaya utang = tingkat bunga yang harus dibayar atas pinjaman baru, yaitu YTM pasar."],
["Cost of debt adalah pembayaran tetap tahunan dibagi harga pasar obligasi","Ini mirip rumus cost of preferred stock (D/P), bukan cost of debt."],
["Cost of debt selalu lebih tinggi daripada cost of equity karena bunga wajib dibayar","Biasanya utang justru lebih murah karena risikonya lebih rendah dan bunganya mengurangi pajak."]],
a:1,x:"Cost of debt = required return kreditor atas utang perusahaan, yaitu:\n• tingkat bunga yang harus dibayar atas pinjaman BARU (suku bunga pasar), atau\n• yield obligasi baru dengan risiko yang sama.\nCost of debt BUKAN coupon rate. Coupon rate ditetapkan saat obligasi diterbitkan dan bisa sudah tidak mencerminkan kondisi pasar. Gunakan YTM."},

{t:3,d:"e",
q:"Mengapa biaya utang (debt) umumnya paling murah dibanding sumber modal lain?",
o:[["Karena bunga utang dapat dikurangkan dari pajak (tax-deductible)","Tepat. Biaya efektif utang = RD × (1 − T)."],
["Karena perusahaan tidak wajib membayar bunga bila sedang merugi","Bunga adalah kewajiban tetap. Justru ekuitas yang tidak punya kewajiban dividen tetap."],
["Karena kreditor ikut menanggung risiko kerugian bisnis perusahaan","Kreditor memiliki klaim lebih dulu dan risikonya lebih rendah. Bukan ini alasan menurut materi."],
["Karena utang tidak memiliki tanggal jatuh tempo pembayaran","Utang justru memiliki jatuh tempo."]],
a:0,x:"Jenis-jenis cost of capital:\n• Debt: biaya lebih rendah karena bunga tax-deductible, biaya setelah pajak = RD(1 − T).\n• Equity (common stock): fleksibel, tidak ada kewajiban dividen tetap.\n• Preferred stock: gabungan karakteristik ekuitas dan utang."},

{t:3,d:"e",
q:"Perusahaan memiliki saham preferen yang membayar dividen tetap $2,50 per tahun. Harga saham preferen saat ini $20. Berapa cost of preferred stock (RP)?",
o:[["8,0%","Rumusnya terbalik: P0/D = 20/2,5 = 8. Yang benar RP = D/P0."],
["12,5%","Tepat. RP = 2,50/20 = 12,5%."],
["2,5%","Ini hanya nilai dividen, belum dibagi harga."],
["12,0%","Ini hasil contoh di materi (3/25), bukan angka soal ini."]],
a:1,x:"Saham preferen membayar dividen konstan setiap periode selamanya (perpetuity), sehingga:\nRP = D / P0 = 2,50 / 20 = 0,125 = 12,5%.\nContoh di materi: dividen $3, harga $25 → RP = 3/25 = 12%.",
xl:{"s":["B3 =B1/B2, lalu ubah format sel menjadi persen (Ctrl+Shift+%)."],"g":[["Dividen preferen","2,5"],["Harga saham preferen","20"],["RP",{"f":"=B1/B2","v":"12,50%"}]]}},

{t:3,d:"e",
q:"Perusahaan diperkirakan membayar dividen $2,00 per lembar tahun depan (D1). Dividen tumbuh konstan 6% per tahun dan harga saham saat ini $40. Berapa cost of equity menurut Dividend Growth Model?",
o:[["5,0%","Ini hanya D1/P0 (dividend yield), belum ditambah growth."],
["11,0%","Tepat. RE = D1/P0 + g = 2/40 + 6% = 5% + 6% = 11%."],
["11,3%","Ini memperlakukan $2,00 sebagai D0 lalu dikali 1,06. Padahal soal sudah memberi D1."],
["6,0%","Ini hanya growth, belum ditambah dividend yield."]],
a:1,x:"Dividend Growth Model (DGM): RE = D1/P0 + g.\n= 2,00/40 + 0,06 = 0,05 + 0,06 = 11%.\nContoh di materi: D1 = 1,50; P0 = 25; g = 5,1% → RE = 0,06 + 0,051 = 11,1%.\nPerhatikan apakah dividen yang diberikan D1 (tahun depan) atau D0 (baru dibayar).",
xl:{"s":["B4 =B1/B2+B3 (dividend yield + growth)."],"g":[["D1","2"],["P0","40"],["g","6%"],["RE",{"f":"=B1/B2+B3","v":"11,00%"}]]}},

{t:3,d:"e",
q:"Saham perusahaan memiliki beta 1,2. Risk-free rate 5% dan market risk premium 7%. Berapa cost of equity menurut CAPM (SML)?",
o:[["13,4%","Tepat. RE = 5% + 1,2 × 7% = 5% + 8,4% = 13,4%."],
["8,4%","Ini hanya premi risiko saham (β × MRP), belum ditambah Rf."],
["7,4%","Ini memperlakukan 7% sebagai return pasar: 5% + 1,2 × (7% − 5%). Padahal yang diberikan adalah premi risiko."],
["12,0%","Ini Rf + MRP tanpa beta (beta dianggap 1)."]],
a:0,x:"CAPM/SML: RE = Rf + β × (market risk premium) = Rf + β × (Rm − Rf).\nKarena yang diberikan market risk PREMIUM (sudah Rm − Rf), langsung dikalikan beta:\nRE = 5% + 1,2 × 7% = 13,4%.\nContoh di materi: β 0,58; Rf 6,1%; MRP 8,6% → RE = 6,1 + 0,58 × 8,6 = 11,1%.",
xl:{"s":["Karena yang diberikan market risk PREMIUM, rumusnya langsung B4 =B2+B1*B3."],"g":[["Beta","1,2"],["Rf","5%"],["Market risk premium","7%"],["RE",{"f":"=B2+B1*B3","v":"13,40%"}]]}},

{t:3,d:"e",
q:"(Soal tugas) Beta saham 0,87, risk-free rate 3,9%, dan expected return pasar (Rm) 12%. Berapa cost of equity (Re) menurut CAPM?",
o:[["14,34%","Ini Rf + β × Rm (lupa mengurangkan Rf dari Rm)."],
["10,95%","Tepat. Re = 3,9% + 0,87 × (12% − 3,9%) = 3,9% + 7,05% = 10,95%."],
["8,10%","Ini hanya Rm − Rf (market risk premium)."],
["7,05%","Ini hanya β × (Rm − Rf), belum ditambah Rf."]],
a:1,x:"Karena yang diberikan adalah RETURN PASAR (Rm), hitung dulu premi risikonya:\nRm − Rf = 12% − 3,9% = 8,1%.\nRe = Rf + β(Rm − Rf) = 3,9% + 0,87 × 8,1% = 3,9% + 7,047% = 10,947% ≈ 10,95%.\nExcel tugas: =B27 + B26*(B28 − B27).",
xl:{"s":["Karena yang diberikan RETURN pasar (Rm), kurangkan Rf dulu: B4 =B2+B1*(B3-B2). Ini persis rumus di Excel tugas."],"g":[["Beta","0,87"],["Rf","3,9%"],["Rm","12%"],["Re",{"f":"=B2+B1*(B3-B2)","v":"10,95%"}]]}},

{t:3,d:"e",
q:"(Soal tugas) Return suatu saham pada tiga kondisi ekonomi: Booming 27% (probabilitas 0,25), Normal 14% (0,55), Resesi 6% (0,20). Berapa expected return saham tersebut?",
o:[["15,67%","Ini rata-rata sederhana (27 + 14 + 6)/3 tanpa memperhitungkan probabilitas."],
["15,65%","Tepat. 0,25(27%) + 0,55(14%) + 0,20(6%) = 6,75% + 7,70% + 1,20% = 15,65%."],
["14,00%","Ini hanya return pada kondisi normal (paling mungkin), bukan expected return."],
["14,60%","Probabilitas booming (0,25) dan resesi (0,20) tertukar."]],
a:1,x:"Expected return = Σ (probabilitas × return).\n= 0,25 × 27% + 0,55 × 14% + 0,20 × 6%\n= 6,75% + 7,70% + 1,20% = 15,65%.\nExcel tugas: =(B13*B14)+(C13*C14)+(D13*D14) atau =SUMPRODUCT(return; probabilitas).",
xl:{"s":["Ketik return di baris 2 dan probabilitas di baris 3, setiap kondisi satu kolom.","B4 =SUMPRODUCT(B2:D2;B3:D3). SUMPRODUCT mengalikan pasangan return × probabilitas lalu menjumlahkannya.","Cek total probabilitas: B5 =SUM(B3:D3) harus 1."],"g":[["","Booming","Normal","Resesi"],["Return","27%","14%","6%"],["Probabilitas","0,25","0,55","0,2"],["Expected return",{"f":"=SUMPRODUCT(B2:D2;B3:D3)","v":"15,65%"}],["Total probabilitas",{"f":"=SUM(B3:D3)","v":"1"}]]}},

{t:3,d:"e",
q:"(Soal tugas) Saham A memberikan return −20% saat ekonomi lesu dan 70% saat booming. Probabilitas masing-masing kondisi 50%. Berapa expected return saham A?",
o:[["−10%","Ini expected return saham B (−30% dan 10%), bukan saham A."],
["25%","Tepat. 0,5(−20%) + 0,5(70%) = −10% + 35% = 25%."],
["50%","Ini selisih/jarak (70 − 20), bukan expected return."],
["35%","Ini hanya kontribusi kondisi booming (0,5 × 70%)."]],
a:1,x:"E(R) = Σ p × R = 0,5 × (−20%) + 0,5 × 70% = −10% + 35% = 25%.\nDi tugas, saham B: 0,5 × (−30%) + 0,5 × 10% = −10%.",
xl:{"s":["B4 =SUMPRODUCT(B2:C2;B3:C3), atau manual =B2*B3+C2*C3."],"g":[["","Lesu","Booming"],["Return saham A","-20%","70%"],["Probabilitas","50%","50%"],["Expected return",{"f":"=SUMPRODUCT(B2:C2;B3:C3)","v":"25,00%"}]]}},

{t:3,d:"e",
q:"Rumus Weighted Average Cost of Capital (WACC) yang benar sesuai materi adalah…",
o:[["WACC = wD·RD + wE·RE + wP·RP","Biaya utang belum disesuaikan dengan pajak."],
["WACC = wD·RD(1 − TC) + wE·RE + wP·RP","Tepat. Hanya komponen utang yang dikalikan (1 − T), karena bunga tax-deductible."],
["WACC = wD·RD(1 − TC) + wE·RE(1 − TC) + wP·RP(1 − TC)","Dividen saham biasa maupun preferen tidak mengurangi pajak, jadi tidak dikali (1 − T)."],
["WACC = (RD + RE + RP) / 3","Ini rata-rata sederhana tanpa bobot struktur modal."]],
a:1,x:"WACC = wD·RD(1 − TC) + wE·RE + wP·RP.\nLangkah:\n1. Hitung biaya tiap sumber modal (RD, RE, RP).\n2. Tentukan persentase (bobot) tiap sumber dalam struktur modal optimal.\n3. Hitung rata-rata tertimbang.\nHanya utang yang disesuaikan pajak karena bunganya tax-deductible."},

{t:3,d:"e",
q:"Yield to maturity (biaya utang sebelum pajak) obligasi perusahaan adalah 8% dan tarif pajak 25%. Berapa biaya utang setelah pajak?",
o:[["8,0%","Ini biaya sebelum pajak."],
["6,0%","Tepat. 8% × (1 − 0,25) = 6%."],
["2,0%","Ini hanya besarnya penghematan pajak (8% × 25%)."],
["10,0%","Pajak justru menurunkan biaya utang, bukan menaikkannya."]],
a:1,x:"After-tax cost of debt = RD × (1 − T) = 8% × 0,75 = 6%.\nBunga mengurangi laba kena pajak, sehingga setiap 1% bunga hanya \"benar-benar\" berbiaya 0,75%.",
xl:{"s":["B3 =B1*(1-B2)."],"g":[["RD sebelum pajak","8%"],["Pajak","25%"],["RD setelah pajak",{"f":"=B1*(1-B2)","v":"6,00%"}]]}},

{t:3,d:"e",
q:"Struktur modal perusahaan: 40% utang dan 60% ekuitas. Biaya utang sebelum pajak 10%, pajak 30%, dan cost of equity 15%. Berapa WACC?",
o:[["13,0%","Biaya utang belum disesuaikan pajak: 0,4 × 10% + 0,6 × 15%."],
["11,8%","Tepat. 0,4 × 10% × (1 − 0,3) + 0,6 × 15% = 2,8% + 9,0% = 11,8%."],
["12,5%","Ini rata-rata sederhana (10% + 15%)/2."],
["10,2%","Bobotnya tertukar: 0,6 × 7% + 0,4 × 15%."]],
a:1,x:"WACC = wD·RD(1 − T) + wE·RE\n= 0,40 × 10% × 0,70 + 0,60 × 15%\n= 2,8% + 9,0% = 11,8%.\nWACC inilah yang dipakai sebagai discount rate proyek dengan risiko setara rata-rata perusahaan.",
xl:{"s":["Ketik bobot di kolom B dan biaya sebelum pajak di kolom C. Pajak di B4.","Biaya setelah pajak: D2 =C2*(1-$B$4) untuk utang, D3 =C3 untuk ekuitas (tidak disesuaikan pajak).","WACC: D5 =SUMPRODUCT(B2:B3;D2:D3), yaitu bobot × biaya lalu dijumlahkan."],"g":[["Sumber","Bobot","Biaya","Biaya setelah pajak"],["Utang","40%","10%",{"f":"=C2*(1-$B$4)","v":"7,00%"}],["Ekuitas","60%","15%",{"f":"=C3","v":"15,00%"}],["Pajak","30%"],["WACC","","",{"f":"=SUMPRODUCT(B2:B3;D2:D3)","v":"11,80%"}]]}},

{t:3,d:"e",
q:"Metode perhitungan cost of equity yang berasumsi dividen tumbuh dengan tingkat konstan adalah…, sedangkan metode yang didasarkan pada risiko sistematis (beta) adalah…",
o:[["Security Market Line (SML); Dividend Growth Model (DGM)","Terbalik. DGM berasumsi growth konstan, SML berbasis beta."],
["Dividend Growth Model (DGM); Security Market Line (SML/CAPM)","Tepat. DGM: RE = D1/P0 + g. SML: RE = Rf + β(Rm − Rf)."],
["Yield to Maturity (YTM); Dividend Growth Model (DGM)","YTM adalah metode cost of debt."],
["Dividend Growth Model (DGM); Yield to Maturity (YTM)","YTM bukan metode cost of equity dan tidak berbasis beta."]],
a:1,x:"Dua metode cost of equity:\n• Dividend Growth Model (DGM): asumsi dividen tumbuh konstan. RE = D1/P0 + g.\n• Security Market Line (SML) = CAPM: berbasis risiko sistematis (beta). RE = Rf + β × MRP.\nDi materi, kedua metode menghasilkan 11,1%, sehingga estimasinya bisa dipercaya."},

{t:3,d:"e",
q:"Struktur modal perusahaan: 30% utang (RD sebelum pajak 10%), 10% saham preferen (RP 9%), dan 60% saham biasa (RE 14%). Tarif pajak 20%. Berapa WACC?",
o:[["12,30%","Biaya utang belum disesuaikan pajak: 3,0% + 0,9% + 8,4%."],
["11,70%","Tepat. 0,3 × 10% × 0,8 + 0,1 × 9% + 0,6 × 14% = 2,4% + 0,9% + 8,4% = 11,7%."],
["11,52%","Saham preferen ikut dikali (1 − T). Dividen preferen tidak tax-deductible."],
["10,33%","Ini rata-rata sederhana (8% + 9% + 14%)/3 tanpa bobot."]],
a:1,x:"WACC = wD·RD(1 − T) + wP·RP + wE·RE\n= 0,30 × 10% × (1 − 0,20) + 0,10 × 9% + 0,60 × 14%\n= 2,4% + 0,9% + 8,4% = 11,7%.\nHanya komponen utang yang disesuaikan pajak.",
xl:{"s":["Ketik bobot (kolom B) dan biaya (kolom C), pajak di B5.","Hanya utang yang dikali (1 − pajak): D2 =C2*(1-$B$5). Preferen dan ekuitas: D3 =C3, D4 =C4.","WACC: D6 =SUMPRODUCT(B2:B4;D2:D4)."],"g":[["Sumber","Bobot","Biaya","Biaya setelah pajak"],["Utang","30%","10%",{"f":"=C2*(1-$B$5)","v":"8,00%"}],["Preferen","10%","9%",{"f":"=C3","v":"9,00%"}],["Ekuitas","60%","14%",{"f":"=C4","v":"14,00%"}],["Pajak","20%"],["WACC","","",{"f":"=SUMPRODUCT(B2:B4;D2:D4)","v":"11,70%"}]]}},

/* ================= MATERI 3 · COST OF CAPITAL · HARD (15) ================= */
{t:3,d:"h",
q:"(Contoh materi) Obligasi perusahaan bersisa 25 tahun, coupon rate 9% dibayar semiannual, dan saat ini dijual $908,72 per $1.000. Berapa cost of debt (YTM tahunan, sebelum pajak)?",
o:[["9,00%","Ini coupon rate. Cost of debt bukan coupon rate."],
["9,90%","Ini current yield (90/908,72), bukan YTM."],
["10,00%","Tepat. YTM per semester 5% × 2 = 10% per tahun."],
["5,00%","Ini YTM per semester. Harus disetahunkan (× 2)."]],
a:2,x:"Data: N = 25 × 2 = 50 periode; kupon per semester = 9% × 1.000 / 2 = $45; PV = −908,72; FV = 1.000.\nExcel: =RATE(50; 45; −908,72; 1000) = 5% per semester.\nYTM tahunan = 5% × 2 = 10%.\nKarena obligasi dijual di bawah par (diskon), YTM (10%) > coupon rate (9%).",
xl:{"s":["Ketik data obligasi di B1:B5 (frekuensi kupon = 2 karena semiannual).","Jumlah periode: B6 =B1*B5 (50). Kupon per periode: B7 =B2*B3/B5 ($45).","YTM per periode: B8 =RATE(B6;B7;-B4;B3). Harga diketik NEGATIF karena itu uang yang kita keluarkan untuk membeli obligasi, sedangkan kupon dan nominal adalah uang masuk.","YTM tahunan: B9 =B8*B5.","Pembanding (pengecoh): current yield B10 =B2*B3/B4."],"g":[["Sisa tahun","25"],["Coupon rate","9%"],["Nilai nominal","1000"],["Harga pasar","908,72"],["Kupon per tahun (kali)","2"],["nper (jumlah periode)",{"f":"=B1*B5","v":"50"}],["pmt (kupon per periode)",{"f":"=B2*B3/B5","v":"45"}],["YTM per semester",{"f":"=RATE(B6;B7;-B4;B3)","v":"5,00%"}],["YTM tahunan",{"f":"=B8*B5","v":"10,00%"}],["Current yield (bukan YTM)",{"f":"=B2*B3/B4","v":"9,90%"}]]}},

{t:3,d:"h",
q:"Obligasi perusahaan bersisa 10 tahun, kupon 8% dibayar tahunan, nilai nominal $1.000, dan harga pasar saat ini $950. Tarif pajak 25%. Berapa biaya utang SETELAH pajak?",
o:[["6,00%","Ini coupon rate (8%) × (1 − 25%). Seharusnya memakai YTM, bukan kupon."],
["6,58%","Tepat. YTM ≈ 8,77%, after-tax = 8,77% × 0,75 ≈ 6,58%."],
["8,77%","Ini YTM sebelum pajak."],
["8,42%","Ini current yield (80/950), bukan YTM."]],
a:1,x:"Langkah 1, YTM: =RATE(10; 80; −950; 1000) = 8,77%.\n(Harga di bawah par, jadi YTM > kupon 8%.)\nLangkah 2, after tax: 8,77% × (1 − 0,25) = 6,58%.\nPerangkap: memakai coupon rate. Ingat: \"The cost of debt is NOT the coupon rate\".",
xl:{"s":["YTM: B6 =RATE(B1;B2*B3;-B4;B3). Urutan argumen RATE: nper; pmt; pv; fv.","After tax: B7 =B6*(1-B5)."],"g":[["Sisa tahun","10"],["Coupon rate","8%"],["Nilai nominal","1000"],["Harga pasar","950"],["Pajak","25%"],["YTM",{"f":"=RATE(B1;B2*B3;-B4;B3)","v":"8,77%"}],["YTM setelah pajak",{"f":"=B6*(1-B5)","v":"6,58%"}]]}},

{t:3,d:"h",
q:"Perusahaan BARU SAJA membayar dividen $2,00 per lembar (D0). Dividen diperkirakan tumbuh konstan 5% per tahun dan harga saham saat ini $30. Berapa cost of equity menurut Dividend Growth Model?",
o:[["11,67%","Ini memakai D0 langsung: 2/30 + 5%. DGM memerlukan D1."],
["12,00%","Tepat. D1 = 2 × 1,05 = 2,10; RE = 2,10/30 + 5% = 7% + 5% = 12%."],
["7,00%","Ini hanya dividend yield D1/P0, belum ditambah g."],
["12,35%","Pertumbuhan dihitung dua kali (D2 dipakai sebagai pembilang)."]],
a:1,x:"DGM memakai dividen TAHUN DEPAN (D1).\nD1 = D0 × (1 + g) = 2,00 × 1,05 = 2,10.\nRE = D1/P0 + g = 2,10/30 + 0,05 = 0,07 + 0,05 = 12%.\nKata kunci: \"baru saja dibayar\" atau \"terakhir dibayar\" = D0; \"diperkirakan dibayar tahun depan\" = D1.",
xl:{"s":["D1 dulu: B4 =B1*(1+B2).","RE: B5 =B4/B3+B2."],"g":[["D0","2"],["g","5%"],["P0","30"],["D1",{"f":"=B1*(1+B2)","v":"2,10"}],["RE",{"f":"=B4/B3+B2","v":"12,00%"}]]}},

{t:3,d:"h",
q:"(Soal tugas) Dividen tahun depan (D1) = Rp125, harga saham saat ini (P0) = Rp953, dan pertumbuhan dividen (g) 7% per tahun. Berapa cost of equity (Re)?",
o:[["13,12%","Ini hanya dividend yield (125/953), belum ditambah g."],
["20,12%","Tepat. Re = 125/953 + 7% = 13,12% + 7% = 20,12%."],
["21,03%","D1 dikalikan lagi dengan (1 + g), padahal 125 sudah D1."],
["14,04%","Pertumbuhan diterapkan ke yield (13,12% × 1,07), bukan ditambahkan."]],
a:1,x:"Re = D1/P0 + g = 125/953 + 0,07 = 0,1312 + 0,07 = 0,2012 = 20,12%.\nExcel tugas: =(B32/B33)+B34.\nPerangkap: D1 sudah dividen tahun depan, jadi jangan dikalikan (1 + g) lagi.",
xl:{"s":["B4 =(B1/B2)+B3, sama seperti Excel tugas."],"g":[["D1","125"],["P0","953"],["g","7%"],["Re",{"f":"=(B1/B2)+B3","v":"20,12%"}]]}},

{t:3,d:"h",
q:"(Soal tugas) Sebuah saham memiliki beta −1,5. Risk-free rate 6,5% dan market risk premium 3%. Berapa required return (Re) saham tersebut menurut CAPM?",
o:[["11,0%","Tanda beta diabaikan (dianggap +1,5)."],
["2,0%","Tepat. Re = 6,5% + (−1,5)(3%) = 6,5% − 4,5% = 2,0%."],
["11,75%","Ini memperlakukan 3% sebagai return pasar: 6,5% − 1,5 × (3% − 6,5%)."],
["−4,5%","Ini hanya β × MRP, belum ditambah Rf."]],
a:1,x:"Re = Rf + β × MRP = 6,5% + (−1,5) × 3% = 6,5% − 4,5% = 2,0%.\nBeta NEGATIF artinya saham bergerak berlawanan dengan pasar (berfungsi sebagai \"asuransi\" portofolio), sehingga required return bisa di bawah risk-free rate.\nExcel tugas: =B21 + B20*(B22). Di tugas, angka 3% dipakai langsung sebagai premi risiko pasar.\nBedakan dengan soal yang memberi Rm (return pasar). Di sana harus dihitung (Rm − Rf) dulu.",
xl:{"s":["Ketik beta negatif: −1,5.","B4 =B2+B1*B3. Tidak ada (Rm − Rf) karena 3% sudah berupa premi risiko pasar."],"g":[["Beta","-1,5"],["Rf","6,5%"],["Market risk premium","3%"],["Re",{"f":"=B2+B1*B3","v":"2,00%"}]]}},

{t:3,d:"h",
q:"(Soal tugas) Saham A: return −20% (lesu) dan 70% (booming). Saham B: −30% (lesu) dan 10% (booming). Probabilitas tiap kondisi 50%, risk-free rate 8%. Berdasarkan expected return, kesimpulan yang tepat adalah…",
o:[["Saham B lebih layak karena kerugian saat lesu (−30%) hanya sedikit lebih buruk dari A (−20%)","E(R) B = −10%, jauh di bawah risk-free rate. Tidak layak."],
["Saham A layak (E(R) = 25% > 8%), sedangkan saham B tidak layak (E(R) = −10% < 8%)","Tepat. Hanya A yang memberi expected return di atas risk-free rate."],
["Kedua saham layak karena masing-masing memiliki peluang 50% untuk menghasilkan return positif","Peluang positif saja tidak cukup. Expected return B negatif."],
["Kedua saham tidak layak karena keduanya bisa menghasilkan return negatif saat kondisi lesu","A tetap layak secara expected return (25% > 8%) walaupun ada kemungkinan rugi."]],
a:1,x:"E(R_A) = 0,5(−20%) + 0,5(70%) = 25%.\nE(R_B) = 0,5(−30%) + 0,5(10%) = −10%.\nRisk-free rate 8% adalah return minimal tanpa risiko. Investor rasional hanya mau menanggung risiko jika expected return > Rf.\nA (25%) > 8% → layak. B (−10%) < 8% → tidak layak; lebih baik investasi bebas risiko.",
xl:{"s":["Expected return A: D2 =SUMPRODUCT(B2:C2;$B$4:$C$4), tarik ke D3 untuk saham B. Tanda $ mengunci baris probabilitas.","Keputusan: E2 =IF(D2>$B$5;\"Layak\";\"Tidak layak\"), tarik ke E3."],"g":[["","Lesu","Booming","E(R)","Keputusan"],["Saham A","-20%","70%",{"f":"=SUMPRODUCT(B2:C2;$B$4:$C$4)","v":"25,00%"},{"f":"=IF(D2>$B$5;\"Layak\";\"Tidak layak\")","v":"Layak"}],["Saham B","-30%","10%",{"f":"=SUMPRODUCT(B3:C3;$B$4:$C$4)","v":"-10,00%"},{"f":"=IF(D3>$B$5;\"Layak\";\"Tidak layak\")","v":"Tidak layak"}],["Probabilitas","50%","50%"],["Risk-free rate","8%"]]}},

{t:3,d:"h",
q:"Return saham X: Booming 25% (probabilitas 30%), Normal 12% (probabilitas 50%), dan Resesi −8% (sisa probabilitasnya). Investor mensyaratkan return minimal 10%. Berapa expected return saham X dan apakah layak?",
o:[["9,67%; tidak layak","Ini rata-rata sederhana (25 + 12 − 8)/3, tanpa bobot probabilitas."],
["11,90%; layak","Tepat. P(resesi) = 20%. E(R) = 7,5% + 6% − 1,6% = 11,9% > 10%."],
["13,50%; layak","Kondisi resesi diabaikan (probabilitas sisa dianggap 0)."],
["10,30%; layak","Probabilitas resesi dianggap 30% sehingga total probabilitas melebihi 100%."]],
a:1,x:"Probabilitas resesi = 100% − 30% − 50% = 20%.\nE(R) = 0,30 × 25% + 0,50 × 12% + 0,20 × (−8%)\n= 7,5% + 6,0% − 1,6% = 11,9%.\n11,9% > 10% (return minimal), jadi layak.\nSelalu cek: total probabilitas harus 100%.",
xl:{"s":["Probabilitas resesi dihitung dari sisanya: D3 =1-B3-C3.","Expected return: B4 =SUMPRODUCT(B2:D2;B3:D3).","Keputusan: B6 =IF(B4>B5;\"Layak\";\"Tidak layak\")."],"g":[["","Booming","Normal","Resesi"],["Return","25%","12%","-8%"],["Probabilitas","30%","50%",{"f":"=1-B3-C3","v":"20,00%"}],["Expected return",{"f":"=SUMPRODUCT(B2:D2;B3:D3)","v":"11,90%"}],["Return minimal","10%"],["Keputusan",{"f":"=IF(B4>B5;\"Layak\";\"Tidak layak\")","v":"Layak"}]]}},

{t:3,d:"h",
q:"Data struktur modal berdasarkan nilai pasar:\n• Utang: 5.000 obligasi, harga $950/lembar, YTM 9%\n• Saham biasa: 200.000 lembar, harga $40, RE 14%\n• Saham preferen: 50.000 lembar, harga $25, RP 10%\nTarif pajak 25%. Berapa WACC?",
o:[["11,95%","Biaya utang belum disesuaikan pajak (memakai 9%, bukan 6,75%)."],
["11,18%","Tepat. Bobot D 33,93%, E 57,14%, P 8,93% → 2,29% + 8,00% + 0,89% = 11,18%."],
["10,25%","Ini rata-rata sederhana (6,75% + 14% + 10%)/3 tanpa bobot nilai pasar."],
["9,50%","Bobot utang (33,93%) dan ekuitas (57,14%) tertukar."]],
a:1,x:"Nilai pasar:\nD = 5.000 × 950 = 4.750.000\nE = 200.000 × 40 = 8.000.000\nP = 50.000 × 25 = 1.250.000\nV = 14.000.000\nBobot: wD = 33,93%; wE = 57,14%; wP = 8,93%.\nRD after tax = 9% × 0,75 = 6,75%.\nWACC = 0,3393 × 6,75% + 0,5714 × 14% + 0,0893 × 10%\n= 2,29% + 8,00% + 0,89% = 11,18%.",
xl:{"s":["Nilai pasar: D2 =B2*C2, tarik ke D4. Total: D5 =SUM(D2:D4).","Bobot: E2 =D2/$D$5, tarik ke E4.","Biaya setelah pajak: G2 =F2*(1-$B$6) untuk utang, G3 =F3 dan G4 =F4.","WACC: B7 =SUMPRODUCT(E2:E4;G2:G4)."],"g":[["Sumber","Jumlah","Harga","Nilai pasar","Bobot","Biaya","Setelah pajak"],["Utang","5000","950",{"f":"=B2*C2","v":"4.750.000"},{"f":"=D2/$D$5","v":"33,93%"},"9%",{"f":"=F2*(1-$B$6)","v":"6,75%"}],["Saham biasa","200000","40",{"f":"=B3*C3","v":"8.000.000"},{"f":"=D3/$D$5","v":"57,14%"},"14%",{"f":"=F3","v":"14,00%"}],["Saham preferen","50000","25",{"f":"=B4*C4","v":"1.250.000"},{"f":"=D4/$D$5","v":"8,93%"},"10%",{"f":"=F4","v":"10,00%"}],["Total","","",{"f":"=SUM(D2:D4)","v":"14.000.000"}],["Pajak","25%"],["WACC",{"f":"=SUMPRODUCT(E2:E4;G2:G4)","v":"11,18%"}]]}},

{t:3,d:"h",
q:"Beta saham perusahaan 1,3, risk-free rate 4%, dan expected return pasar 11%. Biaya utang sebelum pajak 8%, pajak 20%. Struktur modal target 30% utang dan 70% ekuitas. Berapa WACC?",
o:[["11,09%","Tepat. RE = 4% + 1,3 × (11% − 4%) = 13,1%; WACC = 0,3 × 6,4% + 0,7 × 13,1% = 11,09%."],
["14,73%","RE dihitung Rf + β × Rm (lupa mengurangkan Rf) = 18,3%, sehingga WACC = 0,3 × 6,4% + 0,7 × 18,3%."],
["11,57%","Biaya utang belum disesuaikan pajak: 0,3 × 8% + 0,7 × 13,1%."],
["9,93%","Bobot utang dan ekuitas tertukar: 0,7 × 6,4% + 0,3 × 13,1%."]],
a:0,x:"1. Cost of equity (CAPM): RE = 4% + 1,3 × (11% − 4%) = 4% + 9,1% = 13,1%.\n2. After-tax cost of debt: 8% × (1 − 0,2) = 6,4%.\n3. WACC = 0,30 × 6,4% + 0,70 × 13,1% = 1,92% + 9,17% = 11,09%.",
xl:{"s":["RE (CAPM dengan Rm): B8 =B2+B1*(B3-B2).","RD setelah pajak: B9 =B4*(1-B5).","WACC: B10 =B6*B9+B7*B8."],"g":[["Beta","1,3"],["Rf","4%"],["Rm","11%"],["RD sebelum pajak","8%"],["Pajak","20%"],["Bobot utang","30%"],["Bobot ekuitas","70%"],["RE",{"f":"=B2+B1*(B3-B2)","v":"13,10%"}],["RD setelah pajak",{"f":"=B4*(1-B5)","v":"6,40%"}],["WACC",{"f":"=B6*B9+B7*B8","v":"11,09%"}]]}},

{t:3,d:"h",
q:"Lima tahun lalu PT Delta menerbitkan obligasi dengan kupon 6%. Saat ini obligasi tersebut diperdagangkan dengan YTM 9%, dan perusahaan dapat meminjam baru dengan bunga sekitar 9%. Pajak 25%. Biaya utang (setelah pajak) yang tepat untuk menghitung WACC proyek baru adalah…",
o:[["4,50%, karena biaya utang mengikuti kupon obligasi yang benar-benar dibayarkan perusahaan","Memakai kupon 6% × 0,75. Materi: cost of debt BUKAN coupon rate."],
["6,75%, karena biaya utang adalah YTM/bunga pinjaman baru setelah disesuaikan pajak","Tepat. 9% × (1 − 0,25) = 6,75%."],
["9,00%, karena biaya utang harus mencerminkan tingkat bunga pasar sebelum pajak","Bunga pasar memang dipakai, tetapi di WACC biaya utang harus setelah pajak."],
["7,50%, karena biaya utang adalah rata-rata kupon lama dan YTM saat ini","Tidak ada konsep rata-rata kupon dan YTM di materi."]],
a:1,x:"Cost of debt = bunga yang harus dibayar atas pinjaman BARU (suku bunga pasar, YTM), bukan coupon rate historis.\nKupon 6% hanya mencerminkan kondisi pasar lima tahun lalu.\nRD after tax = 9% × (1 − 25%) = 6,75%.",
xl:{"s":["Pakai YTM (bukan kupon): B4 =B2*(1-B3)."],"g":[["Kupon lama (diabaikan)","6%"],["YTM / bunga pinjaman baru","9%"],["Pajak","25%"],["Biaya utang setelah pajak",{"f":"=B2*(1-B3)","v":"6,75%"}]]}},

{t:3,d:"h",
q:"WACC rata-rata perusahaan adalah 10%. Perusahaan mempertimbangkan proyek di bidang baru yang risikonya JAUH lebih tinggi dari bisnis intinya. Pendekatan yang paling tepat menurut konsep discount rate di materi adalah…",
o:[["Tetap memakai WACC 10% karena WACC sudah mencerminkan seluruh biaya modal perusahaan","WACC rata-rata hanya cocok untuk proyek dengan risiko setara rata-rata perusahaan."],
["Memakai discount rate lebih tinggi (risk-adjusted cost of capital) sesuai risiko proyek","Tepat. Semakin besar risiko arus kas, semakin besar discount rate."],
["Memakai risk-free rate agar NPV proyek baru lebih besar dan lebih menarik bagi direksi","Risk-free rate mengabaikan risiko proyek sehingga NPV overstated."],
["Memakai cost of debt saja karena proyek akan didanai sepenuhnya dengan pinjaman bank","Sumber dana spesifik tidak menentukan risiko proyek. Discount rate harus mencerminkan risiko arus kasnya."]],
a:1,x:"Di Capital Budgeting Part 1: discount rate (r) mencerminkan risiko arus kas yang diharapkan. \"Semakin besar risikonya, nilai discount rate akan semakin besar.\"\nr = project's risk-adjusted cost of capital, dipengaruhi suku bunga pasar, market risk aversion, kapasitas utang proyek, dan risiko bisnis proyek.\nWACC adalah discount rate untuk proyek berisiko rata-rata. Untuk proyek lebih berisiko, r harus lebih tinggi."},

{t:3,d:"h",
q:"Saham preferen perusahaan membayar dividen 8% dari nilai par $100 setiap tahun dan saat ini diperdagangkan pada harga $90. Berapa cost of preferred stock?",
o:[["8,00%","Ini persentase dividen terhadap PAR, bukan terhadap harga pasar."],
["8,89%","Tepat. D = 8% × 100 = $8; RP = 8/90 = 8,89%."],
["11,25%","Ini harga dibagi dividen lalu disalahartikan (90/8 = 11,25)."],
["7,20%","Ini 8% × 90 dibagi 100 (dividen dihitung dari harga pasar)."]],
a:1,x:"Dividen preferen dihitung dari PAR: D = 8% × $100 = $8 per tahun.\nCost of preferred stock memakai HARGA PASAR saat ini: RP = D/P0 = 8/90 = 8,89%.\nPerangkap: menganggap RP = tingkat dividen 8%. Ini sama logikanya dengan \"cost of debt bukan coupon rate\".",
xl:{"s":["Dividen dalam dolar: B4 =B1*B2 ($8).","RP memakai harga PASAR: B5 =B4/B3."],"g":[["Nilai par","100"],["Tingkat dividen (% par)","8%"],["Harga pasar","90"],["Dividen per tahun",{"f":"=B1*B2","v":"8"}],["RP",{"f":"=B4/B3","v":"8,89%"}]]}},

{t:3,d:"h",
q:"Perusahaan menargetkan debt-to-equity ratio (D/E) = 0,5. Biaya utang sebelum pajak 9%, pajak 25%, dan cost of equity 15%. Tidak ada saham preferen. Berapa WACC?",
o:[["10,88%","Bobot dianggap 50% : 50%. D/E = 0,5 berarti D : E = 1 : 2, bukan 50% utang."],
["12,25%","Tepat. wD = 1/3, wE = 2/3; WACC = 1/3 × 6,75% + 2/3 × 15% = 2,25% + 10% = 12,25%."],
["13,00%","Biaya utang belum disesuaikan pajak: 1/3 × 9% + 2/3 × 15%."],
["9,50%","Bobotnya tertukar (2/3 utang, 1/3 ekuitas)."]],
a:1,x:"D/E = 0,5 berarti setiap 1 utang ada 2 ekuitas. Total = 3, sehingga:\nwD = 1/3 = 33,3%; wE = 2/3 = 66,7%.\nRD after tax = 9% × 0,75 = 6,75%.\nWACC = 1/3 × 6,75% + 2/3 × 15% = 2,25% + 10% = 12,25%.\nPerangkap umum: menganggap D/E = 0,5 berarti bobot utang 50%.",
xl:{"s":["Bobot dari D/E: wD B2 =B1/(1+B1), wE B3 =1/(1+B1).","WACC: B7 =B2*B4*(1-B5)+B3*B6."],"g":[["D/E","0,5"],["Bobot utang (wD)",{"f":"=B1/(1+B1)","v":"33,33%"}],["Bobot ekuitas (wE)",{"f":"=1/(1+B1)","v":"66,67%"}],["RD sebelum pajak","9%"],["Pajak","25%"],["RE","15%"],["WACC",{"f":"=B2*B4*(1-B5)+B3*B6","v":"12,25%"}]]}},

{t:3,d:"h",
q:"Manakah pernyataan yang BENAR mengenai komponen WACC?",
o:[["Biaya saham preferen dikali (1 − T) karena dividen preferen bersifat tetap seperti bunga","Dividen preferen tetap dibayar dari laba setelah pajak (tidak tax-deductible), sehingga tidak dikali (1 − T)."],
["Saham biasa tanpa kewajiban dividen tetap; biaya utang dikali (1 − T) karena bunga tax-deductible","Tepat. Keduanya sesuai materi: ekuitas fleksibel tanpa kewajiban dividen tetap; utang lebih murah karena bunga tax-deductible."],
["Saham preferen dihitung sebagai anuitas berjangka sehingga biayanya memakai rumus YTM seperti obligasi","Saham preferen adalah perpetuity: RP = D/P0."],
["Bobot WACC sebaiknya selalu memakai nilai buku agar konsisten dengan laporan neraca perusahaan","Materi menekankan bobot pada struktur modal optimal atau target. Dalam praktik umumnya nilai pasar, bukan sekadar nilai buku."]],
a:1,x:"Ringkasan komponen:\n• Debt: biaya lebih rendah, bunga tax-deductible → RD(1 − T).\n• Common equity: fleksibel, tanpa kewajiban dividen tetap. Diestimasi dengan DGM atau CAPM.\n• Preferred stock: gabungan karakteristik ekuitas dan utang; dividen konstan selamanya (perpetuity) → RP = D/P0, TIDAK disesuaikan pajak.\n• Bobot: persentase tiap sumber dalam struktur modal optimal (target)."},

{t:3,d:"h",
q:"Beta saham perusahaan naik dari 1,0 menjadi 1,4 karena bisnisnya makin berisiko. Rf = 5%, market risk premium = 6%. Struktur modal 40% utang (after-tax cost 6%) dan 60% ekuitas. Bagaimana perubahan WACC dan dampaknya pada NPV proyek-proyek perusahaan?",
o:[["WACC naik dari 9,00% menjadi 10,44%, sehingga NPV proyek turun","Tepat. RE naik 11% → 13,4%; WACC = 0,4 × 6% + 0,6 × RE. Discount rate naik, NPV turun."],
["WACC naik dari 9,00% menjadi 10,44%, sehingga NPV proyek naik","Perubahan WACC benar, tetapi discount rate lebih tinggi justru menurunkan NPV."],
["WACC naik dari 11,00% menjadi 13,40%, sehingga NPV proyek turun","Ini perubahan cost of equity, bukan WACC (lupa memasukkan bobot dan biaya utang)."],
["WACC tidak berubah karena beta hanya memengaruhi cost of equity, tidak memengaruhi WACC","Cost of equity adalah komponen WACC, jadi WACC ikut naik."]],
a:0,x:"RE lama = 5% + 1,0 × 6% = 11%. RE baru = 5% + 1,4 × 6% = 13,4%.\nWACC lama = 0,4 × 6% + 0,6 × 11% = 2,4% + 6,6% = 9,00%.\nWACC baru = 0,4 × 6% + 0,6 × 13,4% = 2,4% + 8,04% = 10,44%.\nCost of capital adalah risk indicator: risiko naik, required return naik, discount rate naik, dan NPV proyek turun. Inilah hubungan Cost of Capital dengan Capital Budgeting.",
xl:{"s":["Kolom B = kondisi lama, kolom C = kondisi baru. Ketik beta, Rf, MRP, bobot utang, dan biaya utang setelah pajak.","RE: B5 =B3+B2*B4, salin ke C5.","Bobot ekuitas: B8 =1-B6, salin ke C8.","WACC: B9 =B6*B7+B8*B5, salin ke C9."],"g":[["","Lama","Baru"],["Beta","1","1,4"],["Rf","5%","5%"],["MRP","6%","6%"],["RE",{"f":"=B3+B2*B4","v":"11,00%"},{"f":"=C3+C2*C4","v":"13,40%"}],["Bobot utang","40%","40%"],["RD setelah pajak","6%","6%"],["Bobot ekuitas",{"f":"=1-B6","v":"60,00%"},{"f":"=1-C6","v":"60,00%"}],["WACC",{"f":"=B6*B7+B8*B5","v":"9,00%"},{"f":"=C6*C7+C8*C5","v":"10,44%"}]]}}
];
